import { NextRequest, NextResponse } from 'next/server';
import { getSession } from '@/lib/auth';
import { prisma } from '@/lib/db';

export async function GET(req: NextRequest) {
  const session = await getSession(req);
  if (!session || session.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
  }

  const { searchParams } = new URL(req.url);
  const action = searchParams.get('action');
  const entity = searchParams.get('entity');
  const limit = parseInt(searchParams.get('limit') || '50', 10);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const where: any = {};
  if (action) where.action = action;
  if (entity) where.entity = entity;

  const logs = await prisma.auditLog.findMany({
    where,
    take: limit,
    orderBy: { createdAt: 'desc' },
    include: {
      actor: { select: { id: true, name: true, email: true, role: true } },
    },
  });

  return NextResponse.json({ logs });
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession, comparePassword, hashPassword } from '@/lib/auth';
import { prisma } from '@/lib/db';
import { logAudit } from '@/services/audit.service';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const user = await prisma.user.findFirst({
      where: {
        OR: [
          { id: session.id },
          ...(session.email ? [{ email: session.email.toLowerCase().trim() }] : []),
          ...(session.email ? [{ email: session.email.trim() }] : []),
        ],
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        active: true,
        phone: true,
        designation: true,
        department: true,
        dateOfJoining: true,
        emergencyContact: true,
        routingAvailable: true,
        teamId: true,
        team: {
          select: {
            id: true,
            name: true,
          },
        },
        leaveRequests: {
          orderBy: { createdAt: 'desc' },
          take: 5,
          select: {
            id: true,
            leaveType: true,
            startDate: true,
            endDate: true,
            daysCount: true,
            reason: true,
            status: true,
            reviewComment: true,
            createdAt: true,
          },
        },
        createdAt: true,
        lastLoginAt: true,
        _count: {
          select: {
            ownedLeads: true,
            createdMeetings: true,
          },
        },
      },
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    let effectiveTeam = user.team;
    let effectiveTeamId = user.teamId;

    // Self-healing: If user is TEAM_LEAD but teamId is null on user model, check team relations
    if (!effectiveTeamId && user.role === 'TEAM_LEAD') {
      const foundTeam = await prisma.team.findFirst({
        where: { members: { some: { id: user.id } } },
        select: { id: true, name: true },
      });
      if (foundTeam) {
        effectiveTeam = foundTeam;
        effectiveTeamId = foundTeam.id;
        await prisma.user.update({
          where: { id: user.id },
          data: { teamId: foundTeam.id },
        });
      }
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let teamStats: any = null;
    if (user.role === 'TEAM_LEAD' && effectiveTeamId) {
      const [membersCount, activeLeadsCount, upcomingMeetingsCount] = await Promise.all([
        prisma.user.count({
          where: { teamId: effectiveTeamId, role: 'EXECUTIVE', active: true },
        }),
        prisma.lead.count({
          where: {
            currentCategory: 'ACTIVE',
            currentOwner: { teamId: effectiveTeamId },
          },
        }),
        prisma.meeting.count({
          where: {
            status: 'UPCOMING',
            createdBy: { teamId: effectiveTeamId },
          },
        }),
      ]);

      teamStats = {
        membersCount,
        activeLeadsCount,
        upcomingMeetingsCount,
      };
    }

    const fullUser = {
      ...user,
      teamId: effectiveTeamId,
      team: effectiveTeam,
      teamStats,
    };

    const res = NextResponse.json({ user: fullUser });

    // Self-healing: if session ID or teamId in cookie differs, update cookie
    if (
      session.id !== user.id ||
      session.teamId !== effectiveTeamId ||
      session.role !== user.role ||
      session.name !== user.name
    ) {
      const { signToken, AUTH_COOKIE_NAME } = await import('@/lib/auth');
      const token = signToken({
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role as any,
        teamId: effectiveTeamId,
        teamName: effectiveTeam?.name || null,
      });
      res.cookies.set(AUTH_COOKIE_NAME, token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        path: '/',
        maxAge: 60 * 60 * 24 * 7,
      });
    }

    return res;
  } catch (error) {
    console.error('Fetch profile error:', error);
    return NextResponse.json({ error: 'Failed to fetch profile' }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = await req.json();
    const {
      name,
      phone,
      emergencyContact,
      routingAvailable,
      currentPassword,
      newPassword,
    } = body;

    const user = await prisma.user.findFirst({
      where: {
        OR: [
          { id: session.id },
          ...(session.email ? [{ email: session.email.toLowerCase().trim() }] : []),
          ...(session.email ? [{ email: session.email.trim() }] : []),
        ],
      },
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const updateData: any = {};

    if (name && typeof name === 'string' && name.trim()) {
      updateData.name = name.trim();
    }

    if (phone !== undefined) {
      updateData.phone = phone ? phone.trim() : null;
    }

    if (emergencyContact !== undefined) {
      updateData.emergencyContact = emergencyContact ? emergencyContact.trim() : null;
    }

    if (typeof routingAvailable === 'boolean') {
      updateData.routingAvailable = routingAvailable;
    }

    // Handle Password Change if requested
    if (newPassword) {
      if (!currentPassword) {
        return NextResponse.json(
          { error: 'Current password is required to set a new password' },
          { status: 400 }
        );
      }

      const isCurrentValid = await comparePassword(currentPassword, user.passwordHash);
      if (!isCurrentValid) {
        return NextResponse.json(
          { error: 'Incorrect current password provided' },
          { status: 400 }
        );
      }

      if (newPassword.length < 6) {
        return NextResponse.json(
          { error: 'New password must be at least 6 characters long' },
          { status: 400 }
        );
      }

      updateData.passwordHash = await hashPassword(newPassword);
    }

    const updatedUser = await prisma.user.update({
      where: { id: user.id },
      data: updateData,
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        phone: true,
        designation: true,
        department: true,
        emergencyContact: true,
        routingAvailable: true,
        teamId: true,
        team: { select: { id: true, name: true } },
        updatedAt: true,
      },
    });

    await logAudit({
      actorId: user.id,
      action: newPassword ? 'CHANGE_PASSWORD' : 'UPDATE_PROFILE',
      entity: 'USER',
      entityId: user.id,
      metadata: {
        updatedFields: Object.keys(updateData).filter((k) => k !== 'passwordHash'),
        passwordChanged: Boolean(newPassword),
      },
    });

    const res = NextResponse.json({ success: true, user: updatedUser });

    // Self-healing: if session ID in cookie was from a previous seed or name changed, update cookie
    if (session.id !== user.id || (name && name.trim() !== session.name)) {
      const { signToken, AUTH_COOKIE_NAME } = await import('@/lib/auth');
      const token = signToken({
        id: user.id,
        name: updatedUser.name,
        email: updatedUser.email,
        role: updatedUser.role as any,
        teamId: updatedUser.teamId,
        teamName: updatedUser.team?.name || null,
      });
      res.cookies.set(AUTH_COOKIE_NAME, token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        path: '/',
        maxAge: 60 * 60 * 24 * 7,
      });
    }

    return res;
  } catch (error) {
    console.error('Update profile error:', error);
    return NextResponse.json({ error: 'Failed to update profile' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession } from '@/lib/auth';
import { prisma } from '@/lib/db';
import { logAudit } from '@/services/audit.service';

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { id } = await params;
  if (!id) {
    return NextResponse.json({ error: 'Task ID is required' }, { status: 400 });
  }

  try {
    const task = await prisma.executiveTask.findUnique({
      where: { id },
      include: {
        assignee: { select: { id: true, name: true, teamId: true } },
      },
    });

    if (!task) {
      return NextResponse.json({ error: 'Task not found' }, { status: 404 });
    }

    // Permission check
    let allowed = false;
    if (session.role === 'ADMIN' || session.role === 'HR') {
      allowed = true;
    } else if (session.role === 'EXECUTIVE' && task.assigneeId === session.id) {
      allowed = true;
    } else if (session.role === 'TEAM_LEAD' && session.teamId && task.assignee?.teamId === session.teamId) {
      allowed = true;
    }

    if (!allowed) {
      return NextResponse.json({ error: 'Forbidden: You cannot modify this task' }, { status: 403 });
    }

    const body = await req.json();
    const { status, completed } = body;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const updateData: any = {};

    if (status === 'COMPLETED' || completed === true) {
      updateData.status = 'COMPLETED';
      updateData.completedAt = new Date();
    } else if (status === 'PENDING' || completed === false) {
      updateData.status = 'PENDING';
      updateData.completedAt = null;
    } else if (status === 'OVERDUE') {
      updateData.status = 'OVERDUE';
    }

    const updatedTask = await prisma.executiveTask.update({
      where: { id },
      data: updateData,
      include: {
        assignee: { select: { id: true, name: true, email: true } },
        createdBy: { select: { id: true, name: true, role: true } },
      },
    });

    await logAudit({
      actorId: session.id,
      action: updateData.status === 'COMPLETED' ? 'COMPLETE_TASK' : 'UPDATE_TASK_STATUS',
      entity: 'TASK',
      entityId: id,
      metadata: {
        newStatus: updatedTask.status,
        completedAt: updatedTask.completedAt,
      },
    });

    return NextResponse.json({ success: true, task: updatedTask });
  } catch (error) {
    console.error('Error updating task:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function DELETE(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { id } = await params;
  if (!id) {
    return NextResponse.json({ error: 'Task ID is required' }, { status: 400 });
  }

  try {
    const task = await prisma.executiveTask.findUnique({ where: { id } });
    if (!task) {
      return NextResponse.json({ error: 'Task not found' }, { status: 404 });
    }

    if (session.role !== 'ADMIN' && session.role !== 'HR' && task.createdById !== session.id) {
      return NextResponse.json({ error: 'Forbidden: Only Admin, HR, or creator can delete this task' }, { status: 403 });
    }

    await prisma.executiveTask.delete({ where: { id } });

    await logAudit({
      actorId: session.id,
      action: 'DELETE_TASK',
      entity: 'TASK',
      entityId: id,
    });

    return NextResponse.json({ success: true, message: 'Task deleted successfully' });
  } catch (error) {
    console.error('Error deleting task:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession } from '@/lib/auth';
import { prisma } from '@/lib/db';
import { canAssignExecutiveTasks } from '@/lib/permissions';
import { logAudit } from '@/services/audit.service';

export async function GET(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(req.url);
  const dateParam = searchParams.get('date');
  const allParam = searchParams.get('all') === 'true';
  const statusParam = searchParams.get('status');
  const assigneeIdParam = searchParams.get('assigneeId');

  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const currentTimeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const where: any = {};

  if (session.role === 'EXECUTIVE') {
    where.assigneeId = session.id;
    if (!allParam) {
      where.dueDate = dateParam || todayStr;
    }
  } else if (session.role === 'TEAM_LEAD') {
    if (session.teamId) {
      where.assignee = { teamId: session.teamId };
    } else {
      where.assigneeId = session.id;
    }
    if (!allParam && (dateParam || !allParam)) {
      where.dueDate = dateParam || todayStr;
    }
  } else if (session.role === 'ADMIN' || session.role === 'HR') {
    if (assigneeIdParam) {
      where.assigneeId = assigneeIdParam;
    }
    if (dateParam) {
      where.dueDate = dateParam;
    } else if (!allParam) {
      where.dueDate = todayStr;
    }
  }

  if (statusParam) {
    where.status = statusParam;
  }

  // Fetch tasks
  let tasks = await prisma.executiveTask.findMany({
    where,
    include: {
      assignee: {
        select: {
          id: true,
          name: true,
          email: true,
          designation: true,
          role: true,
        },
      },
      createdBy: {
        select: {
          id: true,
          name: true,
          email: true,
          role: true,
        },
      },
    },
    orderBy: [
      { priority: 'desc' }, // HIGH first
      { dueTime: 'asc' },
      { createdAt: 'desc' },
    ],
  });

  // Evaluate and sync overdue tasks:
  // If task is PENDING and due date < today OR (due date === today && due time < currentTime), mark OVERDUE
  const overdueTaskIds: string[] = [];
  tasks = tasks.map((task) => {
    if (task.status === 'PENDING') {
      const isPastDate = task.dueDate < todayStr;
      const isPastTimeToday = task.dueDate === todayStr && task.dueTime < currentTimeStr;
      if (isPastDate || isPastTimeToday) {
        overdueTaskIds.push(task.id);
        return { ...task, status: 'OVERDUE' };
      }
    }
    return task;
  });

  if (overdueTaskIds.length > 0) {
    await prisma.executiveTask.updateMany({
      where: { id: { in: overdueTaskIds } },
      data: { status: 'OVERDUE' },
    });
  }

  const total = tasks.length;
  const completed = tasks.filter((t) => t.status === 'COMPLETED').length;
  const overdue = tasks.filter((t) => t.status === 'OVERDUE').length;
  const pending = tasks.filter((t) => t.status === 'PENDING').length;

  return NextResponse.json({
    tasks,
    stats: {
      total,
      completed,
      overdue,
      pending,
      completionRate: total > 0 ? Math.round((completed / total) * 100) : 0,
    },
  });
}

export async function POST(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (!canAssignExecutiveTasks(session)) {
    return NextResponse.json(
      { error: 'Forbidden: Only Admin and HR can assign tasks to executives' },
      { status: 403 }
    );
  }

  try {
    const body = await req.json();
    const { title, description, priority, target, assigneeId, dueDate, dueTime } = body;

    if (!title || typeof title !== 'string' || !title.trim()) {
      return NextResponse.json({ error: 'Task title is required' }, { status: 400 });
    }

    const now = new Date();
    const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const targetDueDate = dueDate && /^\d{4}-\d{2}-\d{2}$/.test(dueDate) ? dueDate : todayStr;
    const targetDueTime = dueTime && /^\d{2}:\d{2}$/.test(dueTime) ? dueTime : '18:00';
    const taskPriority = ['HIGH', 'NORMAL', 'LOW'].includes(priority) ? priority : 'NORMAL';

    const creatorLabel = session.role === 'HR' ? 'HR Department' : 'Administration';

    if (target === 'ALL') {
      // Find all active executives
      const executives = await prisma.user.findMany({
        where: {
          role: 'EXECUTIVE',
          active: true,
        },
        select: { id: true, name: true, email: true },
      });

      if (executives.length === 0) {
        return NextResponse.json({ error: 'No active executives found to assign task' }, { status: 400 });
      }

      // Batch create tasks & notifications
      const createdTasks = await prisma.$transaction(async (tx) => {
        const tasks = [];
        for (const exec of executives) {
          const task = await tx.executiveTask.create({
            data: {
              title: title.trim(),
              description: description ? description.trim() : null,
              priority: taskPriority,
              dueDate: targetDueDate,
              dueTime: targetDueTime,
              status: 'PENDING',
              assigneeId: exec.id,
              createdById: session.id,
            },
          });
          tasks.push(task);

          await tx.notification.create({
            data: {
              userId: exec.id,
              type: 'TASK_ASSIGNED',
              title: `Daily Task Assigned: ${title.trim()}`,
              message: `${session.name} (${creatorLabel}) assigned a task due on ${targetDueDate} by ${targetDueTime}. Priority: ${taskPriority}.`,
              link: '/dashboard/executive/dashboard',
            },
          });
        }
        return tasks;
      });

      await logAudit({
        actorId: session.id,
        action: 'ASSIGN_TASKS_BROADCAST',
        entity: 'TASK',
        metadata: {
          title: title.trim(),
          priority: taskPriority,
          targetDueDate,
          targetDueTime,
          executivesCount: executives.length,
        },
      });

      return NextResponse.json({
        success: true,
        count: createdTasks.length,
        message: `Task successfully assigned to all ${createdTasks.length} active executives.`,
      });
    } else {
      // Specific executive assignment
      if (!assigneeId) {
        return NextResponse.json(
          { error: 'Assignee executive ID is required for individual assignment' },
          { status: 400 }
        );
      }

      const executive = await prisma.user.findFirst({
        where: {
          id: assigneeId,
          role: 'EXECUTIVE',
          active: true,
        },
      });

      if (!executive) {
        return NextResponse.json(
          { error: 'Specified user was not found or is not an active executive' },
          { status: 404 }
        );
      }

      const task = await prisma.$transaction(async (tx) => {
        const createdTask = await tx.executiveTask.create({
          data: {
            title: title.trim(),
            description: description ? description.trim() : null,
            priority: taskPriority,
            dueDate: targetDueDate,
            dueTime: targetDueTime,
            status: 'PENDING',
            assigneeId: executive.id,
            createdById: session.id,
          },
          include: {
            assignee: { select: { id: true, name: true, email: true } },
            createdBy: { select: { id: true, name: true, role: true } },
          },
        });

        await tx.notification.create({
          data: {
            userId: executive.id,
            type: 'TASK_ASSIGNED',
            title: `Daily Task Assigned: ${title.trim()}`,
            message: `${session.name} (${creatorLabel}) assigned you a task due on ${targetDueDate} by ${targetDueTime}. Priority: ${taskPriority}.`,
            link: '/dashboard/executive/dashboard',
          },
        });

        return createdTask;
      });

      await logAudit({
        actorId: session.id,
        action: 'ASSIGN_TASK_SPECIFIC',
        entity: 'TASK',
        entityId: task.id,
        metadata: {
          title: title.trim(),
          priority: taskPriority,
          targetDueDate,
          targetDueTime,
          assigneeName: executive.name,
        },
      });

      return NextResponse.json({
        success: true,
        task,
        message: `Task successfully assigned to ${executive.name}.`,
      });
    }
  } catch (error) {
    console.error('Error creating task:', error);
    return NextResponse.json({ error: 'Internal server error while creating task' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession } from '@/lib/auth';
import { prisma } from '@/lib/db';
import { logAudit } from '@/services/audit.service';

export const dynamic = 'force-dynamic';
export const revalidate = 0;

export async function GET(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const where: any = {};
  if (session.role === 'TEAM_LEAD' && session.teamId) {
    where.id = session.teamId;
  }

  const teams = await prisma.team.findMany({
    where,
    include: {
      members: {
        select: {
          id: true,
          name: true,
          email: true,
          role: true,
          active: true,
          _count: {
            select: {
              ownedLeads: { where: { currentCategory: 'ACTIVE' } },
            },
          },
        },
      },
    },
    orderBy: { name: 'asc' },
  });

  // Admins can populate company-wide assignment pickers. Team Leads only
  // receive executives from their own team.
  const availableUsersWhere: {
    active: boolean;
    role: { in: string[] };
    teamId?: string;
  } = {
    active: true,
    role: { in: session.role === 'TEAM_LEAD' ? ['EXECUTIVE'] : ['EXECUTIVE', 'TEAM_LEAD'] },
  };
  if (session.role === 'TEAM_LEAD') {
    const currentUser = await prisma.user.findUnique({
      where: { id: session.id },
      select: { teamId: true },
    });
    availableUsersWhere.teamId = currentUser?.teamId || session.teamId || '__no_team__';
  }

  const availableUsers = await prisma.user.findMany({
    where: availableUsersWhere,
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      teamId: true,
      team: { select: { id: true, name: true } },
    },
    orderBy: { name: 'asc' },
  });

  return NextResponse.json(
    { teams, availableUsers },
    {
      headers: {
        'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        Pragma: 'no-cache',
        Expires: '0',
      },
    }
  );
}

export async function POST(req: NextRequest) {
  const session = await getSession(req);
  if (!session || session.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
  }

  try {
    const { name, description, teamLeadId, memberIds } = await req.json();
    if (!name) return NextResponse.json({ error: 'Team name is required' }, { status: 400 });

    // Enforce: Each Team Lead can only lead 1 team
    if (teamLeadId) {
      const leadCandidate = await prisma.user.findUnique({
        where: { id: teamLeadId },
        include: { team: true },
      });
      if (!leadCandidate) {
        return NextResponse.json({ error: 'Selected Team Lead user not found' }, { status: 404 });
      }
      if (leadCandidate.role === 'TEAM_LEAD' && leadCandidate.teamId) {
        return NextResponse.json(
          {
            error: `${leadCandidate.name} is already the Team Lead of "${leadCandidate.team?.name || 'another team'}". Each Team Lead can only lead 1 team.`,
          },
          { status: 400 }
        );
      }
    }

    // Enforce: Active Team Leads cannot be poached as executive members of another team
    if (Array.isArray(memberIds) && memberIds.length > 0) {
      const activeLeads = await prisma.user.findMany({
        where: {
          id: { in: memberIds },
          role: 'TEAM_LEAD',
          teamId: { not: null },
        },
        include: { team: true },
      });
      if (activeLeads.length > 0) {
        const conflicted = activeLeads[0];
        return NextResponse.json(
          {
            error: `${conflicted.name} is already the Team Lead of "${conflicted.team?.name || 'another team'}". A Team Lead cannot be assigned to another team while actively leading a team.`,
          },
          { status: 400 }
        );
      }
    }

    const team = await prisma.$transaction(async (tx) => {
      const created = await tx.team.create({
        data: { name, description },
      });

      // 1. Assign Team Lead if provided
      if (teamLeadId) {
        await tx.user.update({
          where: { id: teamLeadId },
          data: {
            teamId: created.id,
            role: 'TEAM_LEAD',
          },
        });
      }

      // 2. Assign executive members if provided
      if (Array.isArray(memberIds) && memberIds.length > 0) {
        const executiveIds = memberIds.filter((id: string) => id !== teamLeadId);
        if (executiveIds.length > 0) {
          await tx.user.updateMany({
            where: { id: { in: executiveIds } },
            data: { teamId: created.id },
          });
        }
      }

      return tx.team.findUnique({
        where: { id: created.id },
        include: {
          members: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              active: true,
              _count: {
                select: {
                  ownedLeads: { where: { currentCategory: 'ACTIVE' } },
                },
              },
            },
          },
        },
      });
    });

    await logAudit({
      actorId: session.id,
      action: 'CREATE_TEAM',
      entity: 'TEAM',
      entityId: team?.id,
      metadata: { name, teamLeadId, membersCount: memberIds?.length || 0 },
    });

    return NextResponse.json({ team }, { status: 201 });
  } catch (error) {
    console.error('Create team error:', error);
    return NextResponse.json({ error: 'Failed to create team' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession, hashPassword } from '@/lib/auth';
import { prisma } from '@/lib/db';
import { logAudit } from '@/services/audit.service';
import { ensureCoreUsers } from '@/lib/ensure-users';

export const dynamic = 'force-dynamic';
export const revalidate = 0;

export async function GET(req: NextRequest) {
  const session = await getSession(req);
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  await ensureCoreUsers();

  const { searchParams } = new URL(req.url);
  const role = searchParams.get('role');
  const teamId = searchParams.get('teamId');

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const where: any = {};

  if (session.role === 'TEAM_LEAD') {
    // Team Lead sees members of their team
    const currentUser = await prisma.user.findUnique({ where: { id: session.id }, select: { teamId: true } });
    where.teamId = currentUser?.teamId || session.teamId || '__no_team__';
    // Team leads can assign work only to executives, never to another lead.
    where.role = 'EXECUTIVE';
  } else if (session.role === 'EXECUTIVE') {
    // Executive can only list peers in active list for collaboration or assignment reference
    where.active = true;
  }

  if (role) where.role = role;
  if (teamId && session.role === 'ADMIN') where.teamId = teamId;

  const users = await prisma.user.findMany({
    where,
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      active: true,
      phone: true,
      designation: true,
      department: true,
      dateOfJoining: true,
      baseSalary: true,
      emergencyContact: true,
      routingAvailable: true,
      teamId: true,
      team: { select: { id: true, name: true } },
      createdAt: true,
      lastLoginAt: true,
      _count: {
        select: {
          ownedLeads: { where: { currentCategory: 'ACTIVE' } },
          callLogs: true,
          createdMeetings: true,
        },
      },
    },
    orderBy: { name: 'asc' },
  });

  return NextResponse.json(
    { users },
    {
      headers: {
        'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        Pragma: 'no-cache',
        Expires: '0',
      },
    }
  );
}

export async function POST(req: NextRequest) {
  const session = await getSession(req);
  if (!session || (session.role !== 'ADMIN' && session.role !== 'HR')) {
    return NextResponse.json({ error: 'Forbidden: Admin or HR access required' }, { status: 403 });
  }

  try {
    const {
      name,
      email,
      password,
      role,
      teamId,
      phone,
      designation,
      department,
      baseSalary,
      emergencyContact,
      routingAvailable,
    } = await req.json();

    if (!name || !email || !password || !role) {
      return NextResponse.json({ error: 'Name, email, password, and role are required' }, { status: 400 });
    }

    if (session.role === 'HR' && role !== 'EXECUTIVE' && role !== 'TEAM_LEAD') {
      return NextResponse.json(
        { error: 'Forbidden: HR is only authorized to create Sales Executives or Team Leads' },
        { status: 403 }
      );
    }

    const existing = await prisma.user.findUnique({ where: { email: email.toLowerCase().trim() } });
    if (existing) {
      return NextResponse.json({ error: 'User with this email already exists' }, { status: 400 });
    }

    const passwordHash = await hashPassword(password);

    const newUser = await prisma.user.create({
      data: {
        name,
        email: email.toLowerCase().trim(),
        passwordHash,
        role,
        teamId: teamId || null,
        phone: phone || null,
        designation: designation || null,
        department: department || (role === 'HR' ? 'Human Resources' : 'Sales'),
        baseSalary: baseSalary ? parseFloat(baseSalary) : null,
        emergencyContact: emergencyContact || null,
        routingAvailable: routingAvailable ?? true,
        active: true,
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        active: true,
        teamId: true,
        phone: true,
        designation: true,
        department: true,
      },
    });

    await logAudit({
      actorId: session.id,
      action: 'CREATE_USER',
      entity: 'USER',
      entityId: newUser.id,
      metadata: { name: newUser.name, email: newUser.email, role: newUser.role },
    });

    return NextResponse.json({ user: newUser }, { status: 201 });
  } catch (error) {
    console.error('Create user error:', error);
    return NextResponse.json({ error: 'Failed to create user' }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest) {
  const session = await getSession(req);
  if (!session || session.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
  }

  try {
    const {
      id,
      name,
      email,
      password,
      role,
      teamId,
      phone,
      designation,
      department,
      baseSalary,
      emergencyContact,
      routingAvailable,
      active,
    } = await req.json();

    if (!id) return NextResponse.json({ error: 'User ID is required' }, { status: 400 });

    const dataToUpdate: any = {};
    if (name !== undefined) dataToUpdate.name = name;
    if (email !== undefined) dataToUpdate.email = email.toLowerCase().trim();
    if (role !== undefined) dataToUpdate.role = role;
    if (teamId !== undefined) dataToUpdate.teamId = teamId || null;
    if (phone !== undefined) dataToUpdate.phone = phone || null;
    if (designation !== undefined) dataToUpdate.designation = designation || null;
    if (department !== undefined) dataToUpdate.department = department || null;
    if (baseSalary !== undefined) dataToUpdate.baseSalary = baseSalary ? parseFloat(baseSalary) : null;
    if (emergencyContact !== undefined) dataToUpdate.emergencyContact = emergencyContact || null;
    if (routingAvailable !== undefined) dataToUpdate.routingAvailable = routingAvailable;
    if (active !== undefined) dataToUpdate.active = active;

    if (password && password.trim().length > 0) {
      dataToUpdate.passwordHash = await hashPassword(password.trim());
    }

    const updated = await prisma.user.update({
      where: { id },
      data: dataToUpdate,
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        active: true,
        teamId: true,
        phone: true,
        designation: true,
        department: true,
        baseSalary: true,
        emergencyContact: true,
        routingAvailable: true,
      },
    });

    await logAudit({
      actorId: session.id,
      action: 'UPDATE_USER',
      entity: 'USER',
      entityId: updated.id,
      metadata: { name: updated.name, role: updated.role, active: updated.active },
    });

    return NextResponse.json({ user: updated });
  } catch (error: any) {
    console.error('Update user error:', error);
    if (error?.code === 'P2025') {
      return NextResponse.json({ error: 'User no longer exists. Refresh the user directory and try again.' }, { status: 404 });
    }
    return NextResponse.json({ error: error.message || 'Failed to update user' }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest) {
  const session = await getSession(req);
  if (!session || session.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden: Admin access required to delete users' }, { status: 403 });
  }

  try {
    let body: any = {};
    try {
      body = await req.json();
    } catch {
      // Body may be empty if passing query parameter
      body = {};
    }
    const { id, ids } = body;
    const queryId = req.nextUrl?.searchParams?.get('id');
    const targetIds: string[] = Array.isArray(ids) ? ids : id ? [id] : queryId ? [queryId] : [];

    if (targetIds.length === 0) {
      return NextResponse.json({ error: 'User ID(s) required' }, { status: 400 });
    }

    // Safety constraint: Prevent current logged in admin from deleting self
    const safeIds = targetIds.filter((userId) => userId !== session.id);
    if (safeIds.length === 0) {
      return NextResponse.json({ error: 'Cannot delete your own active administrator account' }, { status: 400 });
    }

    const usersToDelete = await prisma.user.findMany({
      where: { id: { in: safeIds } },
      select: { id: true, name: true, email: true },
    });

    await prisma.$transaction(async (tx) => {
      // 1. Unassign user owned leads
      await tx.lead.updateMany({
        where: { currentOwnerId: { in: safeIds } },
        data: { currentOwnerId: null, isNewToMe: false },
      });

      // 2. Delete tasks assigned to or created by these users
      await tx.executiveTask.deleteMany({
        where: {
          OR: [
            { assigneeId: { in: safeIds } },
            { createdById: { in: safeIds } },
          ],
        },
      });

      // 3. Delete attendance, leaves, notifications, targets
      await tx.attendance.deleteMany({ where: { userId: { in: safeIds } } });
      await tx.leaveRequest.deleteMany({ where: { userId: { in: safeIds } } });
      await tx.notification.deleteMany({ where: { userId: { in: safeIds } } });
      await tx.salesTarget.deleteMany({ where: { userId: { in: safeIds } } });

      // 4. For foreign key restricted relations (LeadUpdate, LeadAssignment, CallLog, Meeting, LeadStatusHistory),
      // reassign foreign key author to current admin so database integrity and history are preserved
      await tx.leadUpdate.updateMany({
        where: { userId: { in: safeIds } },
        data: { userId: session.id },
      });
      await tx.leadAssignment.updateMany({
        where: { performedById: { in: safeIds } },
        data: { performedById: session.id },
      });
      await tx.leadAssignment.updateMany({
        where: { previousOwnerId: { in: safeIds } },
        data: { previousOwnerId: null },
      });
      await tx.leadAssignment.updateMany({
        where: { newOwnerId: { in: safeIds } },
        data: { newOwnerId: null },
      });
      await tx.callLog.updateMany({
        where: { userId: { in: safeIds } },
        data: { userId: session.id },
      });
      await tx.leadStatusHistory.updateMany({
        where: { userId: { in: safeIds } },
        data: { userId: session.id },
      });
      await tx.meeting.updateMany({
        where: { createdById: { in: safeIds } },
        data: { createdById: session.id },
      });

      // 5. Delete the User records
      await tx.user.deleteMany({
        where: { id: { in: safeIds } },
      });
    });

    await logAudit({
      actorId: session.id,
      action: 'DELETE_USER',
      entity: 'USER',
      metadata: { deletedCount: safeIds.length, users: usersToDelete },
    });

    return NextResponse.json({
      success: true,
      deletedCount: safeIds.length,
      deletedUsers: usersToDelete,
    });
  } catch (error: any) {
    console.error('Delete user error:', error);
    return NextResponse.json({ error: error.message || 'Failed to delete user(s)' }, { status: 500 });
  }
}

