              {currentList.map((lead) => (
                <LeadCard
                  key={lead.id}
                  lead={lead}
                  canReassign={true}
                  canDelete={true}
                  selectable={true}
                  isSelected={selectedIds.includes(lead.id)}
                  onToggleSelect={handleToggleSelect}
                  showStory={true}
                  onUpdate={() => setSelectedLeadForUpdate(lead)}
                  onReassign={() => setSelectedLeadForReassign(lead)}
                  onDelete={() => setDeletingLead(lead)}
                />
              ))}
            </div>
          )}
        </div>
      )}

      {/* Bulk Action Bar */}
      <BulkActionBar
        selectedIds={selectedIds}
        selectedLeads={currentList.filter((l) => selectedIds.includes(l.id))}
        onClearSelection={() => setSelectedIds([])}
        onSuccess={() => {
          setSelectedIds([]);
          fetchCallingData();
        }}
        executives={assignableExecutives}
        canDelete={true}
        canReassign={true}
      />

      {/* Single Lead Delete Confirmation Modal */}
      <Modal
        isOpen={Boolean(deletingLead)}
        onClose={() => {
          setDeletingLead(null);
          setDeleteError(null);
        }}
        title="Confirm Lead Deletion"
      >
        <div className="space-y-4">
          <div className="flex items-start gap-3 p-3.5 bg-red-50 border border-red-200 rounded-xl text-red-900">
            <AlertTriangle className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
            <div className="text-xs space-y-1">
              <p className="font-bold text-sm">
                Permanently delete lead {deletingLead?.leadNumber} ({deletingLead?.clientName})?
              </p>
              <p className="text-red-700">
                This action cannot be undone. All call logs, history remarks, and scheduled
                follow-ups for this lead will be removed permanently.
              </p>
            </div>
          </div>

          {deleteError && (
            <div className="p-3 bg-red-50 text-red-600 border border-red-200 rounded-lg text-xs">
              {deleteError}
            </div>
          )}

          <div className="flex justify-end gap-2 pt-2 border-t border-[#E5E5E0]">
            <Button
              type="button"
              variant="secondary"
              onClick={() => {
                setDeletingLead(null);
                setDeleteError(null);
              }}
              disabled={deleteLoading}
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={async () => {
                if (!deletingLead) return;
                setDeleteLoading(true);
                setDeleteError(null);
                try {
                  const res = await fetch(`/api/leads/${deletingLead.id}`, {
                    method: 'DELETE',
                  });
                  if (!res.ok) {
                    const errData = await res.json();
                    throw new Error(errData.error || 'Failed to delete lead');
                  }
                  emitCrmSync('calling');
                  emitCrmSync('leads');
                  setDeletingLead(null);
                  fetchCallingData();
                } catch (err: unknown) {
                  setDeleteError(err instanceof Error ? err.message : 'Error deleting lead');
                } finally {
                  setDeleteLoading(false);
                }
              }}
              isLoading={deleteLoading}
            >
              <Trash2 className="w-4 h-4 mr-1.5" /> Permanently Delete Lead
            </Button>
          </div>
        </div>
      </Modal>

      {/* UPDATE MODAL */}
      {selectedLeadForUpdate && (
        <LeadUpdateModal
          isOpen={true}
          onClose={() => setSelectedLeadForUpdate(null)}
          leadId={selectedLeadForUpdate.id}
          leadNumber={selectedLeadForUpdate.leadNumber}
          clientName={selectedLeadForUpdate.clientName}
          currentStatus={selectedLeadForUpdate.currentStatus}
          onSuccess={fetchCallingData}
        />
      )}

      {/* REASSIGN MODAL */}
      {selectedLeadForReassign && (
        <ReassignModal
          isOpen={true}
          onClose={() => setSelectedLeadForReassign(null)}
          leadId={selectedLeadForReassign.id}
          leadNumber={selectedLeadForReassign.leadNumber}
          clientName={selectedLeadForReassign.clientName}
          currentOwnerName={selectedLeadForReassign.currentOwner?.name}
          onSuccess={fetchCallingData}
        />
      )}

    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Sparkles, RefreshCw, Search, Clock, AlertTriangle, UserCheck, X, Download } from 'lucide-react';
