'use client';

import React, { useState, useEffect } from 'react';
import { PhoneCall, AlertTriangle, Clock, Calendar, RefreshCw, Zap, Play, Send } from 'lucide-react';
import { LeadCard } from '@/components/leads/LeadCard';
import { LeadUpdateModal } from '@/components/leads/LeadUpdateModal';
import { AutoDialerModal, AutoDialerLead } from '@/components/calling/AutoDialerModal';
import { Button } from '@/components/ui/Button';
import { useCrmSync } from '@/lib/sync-event';
import { getFastCache, setFastCache } from '@/lib/fast-data';

interface LeadItem {
  id: string;
  leadNumber: string;
  clientName: string;
  phone: string;
  source: string;
  currentStatus: string;
  currentCategory: string;
  isNewToMe: boolean;
  score?: number | null;
  temperature?: string | null;
  nextAction?: string | null;
  nextActionAt?: string | Date | null;
  lastUpdatedAt: string | Date;
  createdAt: string | Date;
  currentOwner?: { id: string; name: string } | null;
  updates?: Array<{ remark: string; createdAt: string | Date }>;
}

interface ExecutiveCallingData {
  overdue: LeadItem[];
  callToday: LeadItem[];
  upcoming: LeadItem[];
  isClockedIn: boolean;
  markOutRequest?: { status: string; reason?: string | null } | null;
}

const DEFAULT_EXEC_CALLING: ExecutiveCallingData = {
  overdue: [],
  callToday: [],
  upcoming: [],
  isClockedIn: false,
  markOutRequest: null,
};

export default function CallingDataPage() {
  const [tab, setTab] = useState<'overdue' | 'today' | 'upcoming'>('today');
  const cacheKey = 'crm:executive:calling_data';

  const [data, setData] = useState<ExecutiveCallingData>(DEFAULT_EXEC_CALLING);
  const [loading, setLoading] = useState(false);
  const [selectedLeadForUpdate, setSelectedLeadForUpdate] = useState<LeadItem | null>(null);
  const [isAutoDialerOpen, setIsAutoDialerOpen] = useState(false);
  const [autoDialerStartIndex, setAutoDialerStartIndex] = useState(0);
  const [requestSubmitting, setRequestSubmitting] = useState(false);
  const [requestMessage, setRequestMessage] = useState('');

  const fetchCallingData = React.useCallback(async (isBackground: boolean | unknown = false) => {
    try {
      const res = await fetch(`/api/calling?_t=${Date.now()}`, {
        cache: 'no-store',
        headers: { 'Cache-Control': 'no-cache' },
      });
      if (res.ok) {
        const json = await res.json();
        const formatted: ExecutiveCallingData = {
          overdue: json.overdue || [],
          callToday: json.callToday || [],
          upcoming: json.upcoming || [],
          isClockedIn: json.isClockedIn !== false,
          markOutRequest: json.markOutRequest || null,
        };
        setData((prev) => {
          const isSame =
            prev.overdue.length === formatted.overdue.length &&
            prev.callToday.length === formatted.callToday.length &&
            prev.upcoming.length === formatted.upcoming.length &&
            prev.callToday.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|') ===
              formatted.callToday.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|') &&
            prev.overdue.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|') ===
              formatted.overdue.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|') &&
            prev.upcoming.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|') ===
              formatted.upcoming.map((l) => `${l.id}:${l.lastUpdatedAt}:${l.currentStatus}`).join('|');

          if (isSame) return prev;
          return formatted;
        });
        setFastCache(cacheKey, formatted, 30000);
      }
    } catch (err) {
      console.error('Error fetching calling data:', err);
    } finally {
      setLoading(false);
    }
  }, [cacheKey]);

  useEffect(() => {
    const cached = getFastCache<ExecutiveCallingData>(cacheKey);
    if (cached) {
      setData(cached);
    } else {
      setLoading(true);
    }

    fetchCallingData(true);

    const interval = setInterval(() => {
      if (typeof document !== 'undefined' && !document.hidden) {
        fetchCallingData(true);
      }
    }, 4000);

    const handleFocus = () => fetchCallingData(true);
    window.addEventListener('focus', handleFocus);
    return () => {
      clearInterval(interval);
      window.removeEventListener('focus', handleFocus);
    };
  }, [fetchCallingData, cacheKey]);

  // Instant 0ms cross-tab and local sync
  useCrmSync(['calling', 'leads', 'all'], () => {
    fetchCallingData(true);
  });

  const currentList =
    tab === 'overdue' ? data.overdue : tab === 'today' ? data.callToday : data.upcoming;

  const activeCallingQueue =
    currentList.length > 0 ? currentList : [...data.callToday, ...data.overdue];

  const submitMarkOutRequest = async () => {
    setRequestSubmitting(true);
    setRequestMessage('');
    try {
      const res = await fetch('/api/hr/mark-out-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'REQUEST',
          reason: 'Executive marked out by mistake and requested calling access.',
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Could not send request');
      setRequestMessage('Request sent to admin. Calling access will unlock after approval.');
      fetchCallingData(true);
    } catch (error) {
      setRequestMessage(error instanceof Error ? error.message : 'Could not send request');
    } finally {
      setRequestSubmitting(false);
    }
  };

  const handleStartAutoDialer = (startIndex?: number) => {
    setAutoDialerStartIndex(startIndex ?? autoDialerStartIndex);
    setIsAutoDialerOpen(true);
  };

  return (
    <div className="space-y-6">
