            <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[#FAF9F5] border border-[#B69A63]/30 text-[11px] font-semibold text-[#7A5B28] shadow-2xs">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              <span className="hidden sm:inline">Live Calling Stream</span>
              <span className="sm:hidden">Live</span>
            </div>
          </div>
          <p className="text-xs text-[#626560] mt-1">
            Prioritized daily queue of inbound callbacks, expo registrations, and campaign outreach.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          {activeCallingQueue.length > 0 && (
            <button
              onClick={() => handleStartAutoDialer()}
              className="px-4 py-2 rounded-xl bg-gradient-to-r from-[#111314] to-[#1E2021] hover:from-[#1E2021] hover:to-[#2A2D2E] text-[#F4F2EC] text-xs font-black uppercase tracking-wider inline-flex items-center gap-2 border border-[#B69A63]/50 shadow-md transition active:scale-[0.99] cursor-pointer"
            >
              <Zap className="w-4 h-4 text-[#D2BE91] animate-pulse" />
              <span>Auto-Dialer ({activeCallingQueue.length})</span>
            </button>
          )}

          <Button size="sm" variant="secondary" onClick={fetchCallingData} isLoading={loading}>
            <RefreshCw className="w-3.5 h-3.5 mr-1" /> Refresh
          </Button>
        </div>
      </div>

      {!data.isClockedIn && (
        <div className="p-4 rounded-2xl bg-[#FAF5EB] border border-[#E8DCBE] text-[#7A5B28] text-sm font-semibold">
          {data.markOutRequest?.status === 'APPROVED'
            ? 'Admin approved your correction. Refreshing your calling queue...'
            : data.markOutRequest?.status === 'PENDING'
            ? 'Your correction request is waiting for admin approval.'
            : 'You marked out for today. Request admin approval if this was a mistake.'}
        </div>
      )}

      {!data.isClockedIn && data.markOutRequest?.status !== 'APPROVED' && (
        <div className="rounded-2xl border border-[#E5E5E0] bg-white p-4 shadow-xs">
          {data.markOutRequest?.status !== 'PENDING' && (
            <button
              type="button"
              onClick={submitMarkOutRequest}
              disabled={requestSubmitting}
              className="inline-flex items-center gap-2 rounded-xl bg-[#171817] px-4 py-2 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-50"
            >
              <Send className="h-3.5 w-3.5" /> Request access
            </button>
          )}
          {requestMessage && <p className="mt-3 text-xs font-semibold text-[#2D5A3C]">{requestMessage}</p>}
        </div>
      )}

      {/* MOBILE POWER DIALER QUICK BANNER */}
      {activeCallingQueue.length > 0 && (
        <div className="rounded-2xl bg-[#111314] border border-[#26282B] p-4 text-[#F4F2EC] shadow-md flex flex-col sm:flex-row sm:items-center justify-between gap-3">
