              <PhoneCall className="w-5 h-5 text-[#D2BE91]" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-xs font-black uppercase tracking-wider text-[#D2BE91]">
                  Mobile Telecalling Auto-Dialer Ready
                </h3>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-[#2A2315] text-[#D2BE91] border border-[#B69A63]/30">
                  {activeCallingQueue.length} In Queue
                </span>
              </div>
              <p className="text-[11px] text-[#8E918B] mt-0.5">
                Auto-dials next prospect, tracks call timer, captures remarks, and auto-queues next lead.
              </p>
            </div>
          </div>

          <button
            onClick={() => handleStartAutoDialer()}
            className="w-full sm:w-auto px-5 py-2.5 rounded-xl bg-gradient-to-r from-[#B69A63] to-[#D2BE91] text-[#111314] text-xs font-black uppercase tracking-wider flex items-center justify-center gap-2 shadow-sm transition active:scale-[0.99] cursor-pointer"
          >
            <Play className="w-3.5 h-3.5 fill-current" />
            <span>Launch Auto-Call Mode</span>
          </button>
        </div>
      )}

      {/* Tabs */}
      <div className="flex items-center space-x-2 border-b border-[#E5E5E0] pb-2 flex-wrap gap-y-2">
        <button
          onClick={() => setTab('overdue')}
          className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition cursor-pointer select-none ${
            tab === 'overdue'
              ? 'bg-[#FDF2F0] text-[#8C332E] border border-[#F1C7C5] shadow-xs'
              : 'text-[#626560] hover:text-[#8C332E] hover:bg-[#FDF2F0]/50'
          }`}
        >
          <AlertTriangle className={`w-3.5 h-3.5 ${tab === 'overdue' ? 'text-[#8C332E]' : 'text-[#8C332E]/70'}`} />
          OVERDUE ({data.overdue.length})
        </button>

        <button
          onClick={() => setTab('today')}
          className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition cursor-pointer select-none ${
            tab === 'today'
              ? 'bg-[#111314] text-[#F4F2EC] border border-[#252829] shadow-xs'
