interface StaffPayrollItem {
  userId: string;
  name: string;
  email: string;
  role: string;
  teamName: string;
  designation: string;
  period: string;
  baseSalary: number;
  targetCalls: number;
  targetMeetings: number;
  targetRevenue: number;
  commissionRate: number;
  bonus: number;
  deductions: number;
  callsCompletedCount: number;
