export const ExecutiveRealtimeListener: React.FC = () => {
  const router = useRouter();

  const lastRefreshRef = React.useRef(0);

  useCrmSync(['leads', 'calling', 'tasks', 'all'], () => {
    const now = Date.now();
    if (now - lastRefreshRef.current > 8000) {
      lastRefreshRef.current = now;
      try {
        router.refresh();
      } catch {}
    }
  });

  return (
    <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[#FAF9F5] border border-[#B69A63]/30 text-[11px] font-semibold text-[#7A5B28] shadow-2xs">
      <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
      <span className="hidden sm:inline">Live Real-time Sync Active</span>
      <span className="sm:hidden">Live</span>
    </div>
  );
};

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useRouter } from 'next/navigation';
import {
  Search,
  User,
  Users,
  Building2,
  Calendar,
  PhoneCall,
  ArrowRight,
  PlusCircle,
  Clock,
  Briefcase,
  X,
  Sparkles,
  ShieldCheck,
  LayoutGrid,
  TrendingUp,
  FileSpreadsheet,
} from 'lucide-react';
import { UserSession } from '@/types';

interface SearchResultItem {
  id: string;
  type: 'lead' | 'user' | 'team' | 'meeting' | 'candidate';
  title: string;
  subtitle: string;
  badge?: string;
  badgeColor?: string;
  url: string;
  metadata?: Record<string, any>;
}

interface CommandPaletteProps {
  user: UserSession;
  isOpen: boolean;
  onClose: () => void;
  onOpenNewLead?: () => void;
}

export const CommandPalette: React.FC<CommandPaletteProps> = ({
  user,
  isOpen,
  onClose,
  onOpenNewLead,
}) => {
  const router = useRouter();
  const [query, setQuery] = useState('');
  const [activeType, setActiveType] = useState<string>('all');
  const [results, setResults] = useState<SearchResultItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number>(0);
  const [mounted, setMounted] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Quick Action items based on role
  const quickActions = [
    ...(user.role === 'ADMIN' && onOpenNewLead
      ? [
          {
            id: 'action-new-lead',
            title: 'Create New Lead',
            subtitle: 'Add a new client dossier manually to CRM',
            icon: PlusCircle,
            badge: 'Admin',
            action: () => {
              onClose();
              onOpenNewLead();
            },
          },
        ]
      : []),
    {
      id: 'action-dialer',
      title: 'Launch Calling Queue',
      subtitle: 'Open telecalling queue with 1-click dials & callbacks',
      icon: PhoneCall,
      badge: 'Speed',
      action: () => {
        onClose();
        router.push(
          user.role === 'ADMIN'
            ? '/dashboard/admin/calling'
            : '/dashboard/executive/calling'
        );
      },
    },
    ...(user.role === 'ADMIN' || user.role === 'TEAM_LEAD'
      ? [
          {
            id: 'action-pipeline',
            title: 'Deals Pipeline (Kanban)',
            subtitle: 'Visual funnel view with live deal stages',
            icon: LayoutGrid,
            badge: 'Pipeline',
            action: () => {
              onClose();
              router.push('/dashboard/admin/pipeline');
            },
          },
          {
            id: 'action-bulk-upload',
            title: 'Bulk Upload Hub',
            subtitle: 'Import CSV calling sheets & lead batches',
            icon: FileSpreadsheet,
            badge: 'Import',
            action: () => {
              onClose();
              router.push('/dashboard/admin/bulk-upload');
            },
          },
        ]
      : []),
    {
      id: 'action-meetings',
      title: 'Meetings & Site Visits Calendar',
      subtitle: 'Scheduled presentations & boardroom meetings',
      icon: Calendar,
      badge: 'Calendar',
      action: () => {
        onClose();
        router.push('/dashboard/meetings');
      },
    },
    {
      id: 'action-attendance',
      title: 'Attendance & Work Status',
      subtitle: 'Daily clock-in logs and shift hours',
      icon: Clock,
      badge: 'HR',
      action: () => {
        onClose();
        router.push(
          user.role === 'HR'
            ? '/dashboard/hr/attendance'
            : '/dashboard/profile'
        );
      },
    },
    {
      id: 'action-profile',
      title: 'My Profile & Security Settings',
      subtitle: 'Contact info, credentials & password',
      icon: ShieldCheck,
      badge: 'Account',
      action: () => {
        onClose();
        router.push('/dashboard/profile');
      },
    },
  ];

  // Focus input on open & lock background scroll
  useEffect(() => {
    if (isOpen) {
      setQuery('');
      setSelectedIndex(0);
      document.body.style.overflow = 'hidden';
      const timer = setTimeout(() => inputRef.current?.focus(), 60);
      return () => {
        clearTimeout(timer);
        document.body.style.overflow = '';
      };
    } else {
      document.body.style.overflow = '';
    }
  }, [isOpen]);

  // Global key listener for Ctrl+K / Cmd+K
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        if (isOpen) {
          onClose();
        } else {
          inputRef.current?.focus();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // Perform search query
  useEffect(() => {
    if (!isOpen) return;

    if (!query.trim()) {
      setResults([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(
          `/api/search?q=${encodeURIComponent(query.trim())}&type=${activeType}`
        );
        if (res.ok) {
          const json = await res.json();
          setResults(json.results || []);
          setSelectedIndex(0);
        }
      } catch (err) {
        console.error('Search error:', err);
      } finally {
        setLoading(false);
      }
    }, 120);

    return () => clearTimeout(timer);
  }, [query, activeType, isOpen]);

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    const totalItems = query.trim() ? results.length : quickActions.length;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((prev) => (prev + 1) % Math.max(1, totalItems));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((prev) => (prev - 1 + totalItems) % Math.max(1, totalItems));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (query.trim() && results[selectedIndex]) {
        handleSelectResult(results[selectedIndex]);
      } else if (!query.trim() && quickActions[selectedIndex]) {
        quickActions[selectedIndex].action();
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    }
  };

  const handleSelectResult = (item: SearchResultItem) => {
    onClose();
    router.push(item.url);
  };

  if (!isOpen || !mounted) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[9999] flex items-start justify-center pt-12 sm:pt-20 px-4 pb-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className="w-full max-w-2xl bg-[#111314] text-[#F4F2EC] rounded-3xl shadow-[0_25px_70px_rgba(0,0,0,0.9)] border border-[#B69A63]/30 overflow-hidden flex flex-col max-h-[85vh] animate-in zoom-in-95 duration-150 relative"
        onKeyDown={handleKeyDown}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search Header Bar */}
        <div className="p-4 sm:p-5 border-b border-[#26282B] flex items-center gap-3.5 bg-[#17181A] relative">
          <div className="w-9 h-9 rounded-xl bg-[#222527] border border-[#B69A63]/40 flex items-center justify-center shrink-0">
            <Search className="w-4 h-4 text-[#D2BE91]" />
          </div>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search leads, phone numbers, staff, teams, meetings..."
            className="w-full bg-transparent text-sm sm:text-base text-[#F4F2EC] placeholder-[#727570] outline-none font-medium"
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="p-1.5 hover:bg-[#26282B] rounded-lg text-[#727570] hover:text-[#F4F2EC] transition cursor-pointer"
              title="Clear input"
            >
              <X className="w-4 h-4" />
            </button>
          )}
          <button
            onClick={onClose}
            className="hidden sm:inline-flex items-center gap-1 px-2.5 py-1 text-[11px] font-mono font-bold text-[#8E918B] bg-[#1E2021] border border-[#2E3133] rounded-lg hover:text-white hover:border-[#B69A63]/50 transition cursor-pointer"
          >
            ESC
          </button>
        </div>

        {/* Category Filters (when search query is active) */}
        {query.trim() && (
          <div className="flex items-center gap-2 px-4 sm:px-5 py-2.5 border-b border-[#222426] bg-[#141517] overflow-x-auto text-xs">
            {[
              { id: 'all', label: 'All Results' },
              { id: 'leads', label: 'Leads' },
              { id: 'users', label: 'Staff' },
              { id: 'teams', label: 'Teams' },
              { id: 'meetings', label: 'Meetings' },
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveType(tab.id)}
                className={`px-3 py-1 rounded-full font-bold text-[11px] transition cursor-pointer shrink-0 ${
                  activeType === tab.id
                    ? 'bg-gradient-to-r from-[#B69A63] to-[#D2BE91] text-[#111314] shadow-sm'
                    : 'text-[#8E918B] hover:text-[#F4F2EC] hover:bg-[#1E2021]'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        )}

        {/* Body Content */}
        <div ref={listRef} className="flex-1 overflow-y-auto p-3 sm:p-4 space-y-1">
          {loading ? (
            <div className="py-14 text-center text-[#8E918B] text-xs sm:text-sm flex flex-col items-center justify-center gap-3">
              <div className="w-6 h-6 border-2 border-[#B69A63] border-t-transparent rounded-full animate-spin" />
              <span>Searching real-time CRM database...</span>
            </div>
          ) : query.trim() ? (
            results.length > 0 ? (
              <div className="space-y-1.5">
                <div className="px-3 py-1 text-[10px] font-black uppercase tracking-widest text-[#B69A63]">
                  Matches Found ({results.length})
                </div>
                {results.map((item, idx) => {
                  const isSelected = idx === selectedIndex;
                  return (
                    <div
                      key={`${item.type}-${item.id}`}
                      onClick={() => handleSelectResult(item)}
                      onMouseEnter={() => setSelectedIndex(idx)}
                      className={`px-3.5 py-3 rounded-2xl cursor-pointer flex items-center justify-between transition-all ${
                        isSelected
                          ? 'bg-[#1E2021] border border-[#B69A63]/60 shadow-lg text-[#F4F2EC]'
                          : 'hover:bg-[#18191B] border border-transparent text-[#AEB1AC]'
                      }`}
                    >
                      <div className="flex items-center gap-3.5 min-w-0">
                        <div
                          className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 border ${
                            item.type === 'lead'
                              ? 'bg-emerald-950/60 text-emerald-400 border-emerald-800/40'
                              : item.type === 'user'
                              ? 'bg-purple-950/60 text-purple-400 border-purple-800/40'
                              : item.type === 'team'
                              ? 'bg-amber-950/60 text-amber-400 border-amber-800/40'
                              : 'bg-blue-950/60 text-blue-400 border-blue-800/40'
                          }`}
                        >
                          {item.type === 'lead' && <User className="w-4 h-4" />}
                          {item.type === 'user' && <Briefcase className="w-4 h-4" />}
                          {item.type === 'team' && <Users className="w-4 h-4" />}
                          {item.type === 'meeting' && <Calendar className="w-4 h-4" />}
                        </div>

                        <div className="min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="font-bold text-sm text-[#F4F2EC] truncate">
                              {item.title}
                            </span>
                            {item.badge && (
                              <span
                                className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
                                  item.badgeColor || 'bg-[#2A2315] text-[#D2BE91] border-[#B69A63]/40'
                                }`}
                              >
                                {item.badge}
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-[#8E918B] truncate mt-0.5">
                            {item.subtitle}
                          </p>
                        </div>
                      </div>

                      <ArrowRight
                        className={`w-4 h-4 shrink-0 ml-2 transition-transform ${
                          isSelected ? 'text-[#D2BE91] translate-x-0.5' : 'text-[#525550]'
                        }`}
                      />
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="py-14 text-center text-[#8E918B]">
                <Search className="w-8 h-8 mx-auto text-[#424540] mb-2" />
                <p className="font-bold text-sm text-[#F4F2EC]">No records match &ldquo;{query}&rdquo;</p>
                <p className="text-xs text-[#727570] mt-1">
                  Try searching by client phone number, email, lead # or staff name.
                </p>
              </div>
            )
          ) : (
            <div className="space-y-1.5">
              <div className="px-3 py-1 text-[10px] font-black uppercase tracking-widest text-[#B69A63] flex items-center justify-between">
                <span>Quick Actions</span>
                <span className="text-[10px] normal-case text-[#626560]">Press ↵ to launch</span>
              </div>
              {quickActions.map((action, idx) => {
                const isSelected = idx === selectedIndex;
                const Icon = action.icon;
                return (
                  <div
                    key={action.id}
                    onClick={action.action}
                    onMouseEnter={() => setSelectedIndex(idx)}
                    className={`px-3.5 py-3 rounded-2xl cursor-pointer flex items-center justify-between transition-all ${
                      isSelected
                        ? 'bg-[#1E2021] border border-[#B69A63]/60 shadow-lg text-[#F4F2EC]'
                        : 'hover:bg-[#18191B] border border-transparent text-[#AEB1AC]'
                    }`}
                  >
                    <div className="flex items-center gap-3.5">
                      <div className="w-9 h-9 rounded-xl bg-[#17181A] border border-[#2A2D2E] text-[#D2BE91] flex items-center justify-center shrink-0">
                        <Icon className="w-4 h-4 text-[#D2BE91]" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <p className="font-bold text-sm text-[#F4F2EC]">{action.title}</p>
                          <span className="text-[9px] font-mono font-bold px-1.5 py-0.2 rounded bg-[#2A2315] text-[#D2BE91] border border-[#B69A63]/30">
                            {action.badge}
                          </span>
                        </div>
                        <p className="text-xs text-[#8E918B] mt-0.5">{action.subtitle}</p>
                      </div>
                    </div>
                    <ArrowRight
                      className={`w-4 h-4 transition-transform ${
                        isSelected ? 'text-[#D2BE91] translate-x-0.5' : 'text-[#525550]'
                      }`}
                    />
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Footer info */}
        <div className="px-4 sm:px-5 py-3 bg-[#17181A] border-t border-[#26282B] text-[11px] text-[#727570] flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="hidden sm:inline">
              <kbd className="font-mono font-bold text-[#D2BE91] bg-[#222527] px-1.5 py-0.5 rounded border border-[#2E3133]">
                ↑
              </kbd>{' '}
              <kbd className="font-mono font-bold text-[#D2BE91] bg-[#222527] px-1.5 py-0.5 rounded border border-[#2E3133]">
                ↓
              </kbd>{' '}
              navigate
            </span>
            <span>
              <kbd className="font-mono font-bold text-[#D2BE91] bg-[#222527] px-1.5 py-0.5 rounded border border-[#2E3133]">
                ↵
              </kbd>{' '}
              select
            </span>
          </div>
          <span className="text-[#D2BE91] font-bold flex items-center gap-1.5">
            <Sparkles className="w-3.5 h-3.5 text-[#B69A63]" /> ORVION OmniSearch
          </span>
        </div>
      </div>
    </div>,
    document.body
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
  LayoutDashboard,
  PhoneCall,
  Clock,
  Calendar,
  User,
  Layers,
  Sparkles,
  TrendingUp,
  Users,
  Building2,
} from 'lucide-react';
import { UserRole } from '@/types';
import clsx from 'clsx';

interface MobileBottomNavProps {
  role: UserRole;
}

interface NavTab {
  label: string;
  href: string;
  icon: React.ComponentType<{ className?: string }>;
}

export const MobileBottomNav: React.FC<MobileBottomNavProps> = ({ role }) => {
  const pathname = usePathname();
  const [optimisticPathname, setOptimisticPathname] = useState(pathname);

  useEffect(() => {
    setOptimisticPathname(pathname);
  }, [pathname]);

  const executiveTabs: NavTab[] = [
    { label: 'Dashboard', href: '/dashboard/executive/dashboard', icon: LayoutDashboard },
    { label: 'Calling', href: '/dashboard/executive/calling', icon: PhoneCall },
    { label: 'Today', href: '/dashboard/executive/today', icon: Clock },
    { label: 'Meetings', href: '/dashboard/meetings', icon: Calendar },
    { label: 'Profile', href: '/dashboard/profile', icon: User },
  ];

  const adminTabs: NavTab[] = [
    { label: 'Leads', href: '/dashboard/admin/dashboard', icon: LayoutDashboard },
    { label: 'Calling', href: '/dashboard/admin/calling', icon: PhoneCall },
    { label: 'All Leads', href: '/dashboard/admin/leads', icon: Layers },
    { label: 'Teams', href: '/dashboard/admin/teams', icon: Building2 },
    { label: 'Profile', href: '/dashboard/profile', icon: User },
  ];

  const teamLeadTabs: NavTab[] = [
    { label: 'Dashboard', href: '/dashboard/team-lead/dashboard', icon: LayoutDashboard },
    { label: 'Today', href: '/dashboard/team-lead/today', icon: Clock },
    { label: 'Calling', href: '/dashboard/team-lead/calling', icon: PhoneCall },
    { label: 'Workflow', href: '/dashboard/team-lead/workflow', icon: TrendingUp },
    { label: 'Meetings', href: '/dashboard/meetings', icon: Calendar },
    { label: 'Profile', href: '/dashboard/profile', icon: User },
  ];

  const hrTabs: NavTab[] = [
    { label: 'Dashboard', href: '/dashboard/hr/dashboard', icon: LayoutDashboard },
    { label: 'Staff', href: '/dashboard/hr/employees', icon: Users },
    { label: 'Attendance', href: '/dashboard/hr/attendance', icon: Clock },
    { label: 'Leaves', href: '/dashboard/hr/leaves', icon: Calendar },
    { label: 'Profile', href: '/dashboard/profile', icon: User },
  ];

  const tabs =
    role === 'ADMIN'
      ? adminTabs
      : role === 'TEAM_LEAD'
      ? teamLeadTabs
      : role === 'HR'
      ? hrTabs
      : executiveTabs;

  const currentPath = (optimisticPathname || pathname || '').split('?')[0];

  return (
    <nav className="lg:hidden fixed bottom-0 left-0 right-0 z-40 bg-[#0B0C0D] border-t border-[#1E2021] text-[#F4F2EC] px-2 py-1.5 pb-[calc(0.5rem+env(safe-area-inset-bottom))] shadow-2xl select-none">
      <div className="flex items-center justify-around">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const targetPath = tab.href.split('?')[0];
          const isActive = currentPath === targetPath;

          return (
            <Link
              key={tab.href}
              href={tab.href}
              prefetch={true}
              onPointerDown={() => setOptimisticPathname(tab.href)}
              onClick={() => setOptimisticPathname(tab.href)}
              className={clsx(
                'flex flex-col items-center justify-center py-1 px-2.5 rounded-xl transition-all duration-100 cursor-pointer relative min-w-[56px] active:scale-95',
                isActive
                  ? 'text-[#D2BE91] font-bold'
                  : 'text-[#8E918B] hover:text-[#F4F2EC] font-medium'
              )}
            >
              <div className="relative">
                <Icon
                  className={clsx(
                    'w-5 h-5 transition-transform duration-150',
                    isActive ? 'scale-110 text-[#B69A63]' : 'text-[#8E918B]'
                  )}
                />
                {isActive && (
                  <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 bg-[#B69A63] rounded-full shadow-[0_0_6px_#B69A63]" />
                )}
              </div>
              <span className="text-[10px] mt-1 tracking-tight truncate max-w-[64px]">
                {tab.label}
              </span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
};

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Bell, Plus, LogOut, CheckCheck, RefreshCw, User, Menu, Search, Sparkles } from 'lucide-react';
import { Button } from '../ui/Button';
import { UserSession } from '@/types';
import { NotificationDrawer, NotificationItem } from '../notifications/NotificationDrawer';
import { CommandPalette } from './CommandPalette';
import { useCrmSync } from '@/lib/sync-event';
import { getFastCache, setFastCache } from '@/lib/fast-data';

interface NavbarProps {
  user: UserSession;
  onOpenNewLead?: () => void;
  onToggleMobileMenu?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ user, onOpenNewLead, onToggleMobileMenu }) => {
  const router = useRouter();
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await fetch('/api/notifications');
      if (res.ok) {
        const data = await res.json();
        const list = data.notifications || [];
        setNotifications(list);
        setFastCache('crm:notifications', list, 30000);
      }
    } catch {
      // silent catch
    }
  }, []);

  useEffect(() => {
    const cachedNotifications = getFastCache<NotificationItem[]>('crm:notifications');
    if (cachedNotifications) {
      setNotifications(cachedNotifications);
    }
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 15000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  useCrmSync(['leads', 'calling', 'tasks', 'all'], () => {
    fetchNotifications();
  });

  useEffect(() => {
    const updateOnlineStatus = () => {
      if (typeof navigator !== 'undefined') {
        setSyncStatus(navigator.onLine ? 'synced' : 'error');
      }
    };
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const handleManualSync = async () => {
    setSyncStatus('syncing');
    try {
      const res = await fetch(`/api/sync/pulse?_t=${Date.now()}`, {
        cache: 'no-store',
        headers: { 'Cache-Control': 'no-cache' },
      });
      if (res.ok) {
        setTimeout(() => setSyncStatus('synced'), 400);
      } else {
        setSyncStatus('error');
      }
    } catch {
      setSyncStatus('error');
    }
  };

  const handleLogout = async () => {
    setIsLoggingOut(true);
    try {
      await fetch('/api/auth/logout', { method: 'POST' });
      router.push('/login');
      router.refresh();
    } catch {
      setIsLoggingOut(false);
    }
  };

  const unreadCount = notifications.filter((n) => !n.read).length;

  return (
    <header
      className="bg-white/95 backdrop-blur-md border-b border-[#E5E5E0] sticky top-0 z-30 shadow-[0_1px_3px_rgba(0,0,0,0.02)] transition-all"
      style={{
        paddingTop: 'env(safe-area-inset-top, 0px)',
      }}
    >
      <div className="h-14 sm:h-16 px-3 sm:px-6 flex items-center justify-between w-full">
        {/* Left: Mobile Hamburger & Team / Sync status / OmniSearch */}
        <div className="flex items-center space-x-2 sm:space-x-4 min-w-0">
          {/* Mobile Hamburger Button */}
          {onToggleMobileMenu && (
            <button
              type="button"
              onClick={onToggleMobileMenu}
              className="lg:hidden p-2 -ml-1 rounded-xl text-[#171817] hover:bg-[#F4F4F1] active:bg-[#ECECE8] transition cursor-pointer shrink-0"
              title="Open Navigation Menu"
              aria-label="Open Navigation Menu"
            >
              <Menu className="w-5 h-5 text-[#171817]" />
            </button>
          )}

          {/* Mobile Logo on small screens */}
          <Link
            href="/dashboard"
            className="flex items-center space-x-2 lg:hidden group shrink-0"
          >
            <img
              src="/logo.png"
              alt="ORVION Logo"
              className="w-7 h-7 rounded-lg object-cover border border-[#B69A63]/50 shadow-xs"
            />
            <div className="flex flex-col">
              <span className="text-xs font-black tracking-widest text-[#171817] uppercase leading-tight">
                ORVION
              </span>
              {user.role === 'ADMIN' && (
                <span className="text-[8px] font-mono font-bold tracking-wider text-[#B69A63] uppercase leading-none hidden xs:block">
                  Admin
                </span>
              )}
            </div>
          </Link>

          {/* OmniSearch Quick Bar */}
          <button
            onClick={() => setIsCommandPaletteOpen(true)}
            className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-[#F8F8F6] hover:bg-[#F4F4F0] border border-[#E5E5E0] rounded-xl text-xs text-zinc-500 transition-all cursor-pointer group"
          >
            <Search className="w-3.5 h-3.5 text-zinc-400 group-hover:text-[#B69A63] transition-colors" />
            <span className="font-medium text-[11px] text-zinc-600">Quick search...</span>
            <kbd className="text-[10px] font-semibold text-zinc-400 bg-white border border-zinc-200 px-1.5 py-0.2 rounded-md shadow-2xs">
              Ctrl+K
            </kbd>
          </button>

          {/* Real-time Sync Indicator */}
          <button
            onClick={handleManualSync}
            title="Click to re-check database sync"
            className="hidden sm:flex items-center space-x-2 px-3 py-1 rounded-full text-xs transition cursor-pointer border bg-[#EDF5F0] border-[#D3E5D9] text-[#2D5A3C] hover:bg-[#E3EFE7]"
          >
            {syncStatus === 'synced' && (
              <>
                <span className="w-1.5 h-1.5 rounded-full bg-[#2D5A3C]"></span>
                <span className="text-[11px] font-medium">Synced with Cloud</span>
              </>
            )}
            {syncStatus === 'syncing' && (
              <>
                <RefreshCw className="w-3 h-3 text-[#626560] animate-spin" />
                <span className="text-[11px] font-medium text-[#626560]">Syncing...</span>
              </>
            )}
            {syncStatus === 'error' && (
              <>
                <span className="w-1.5 h-1.5 rounded-full bg-[#753330]"></span>
                <span className="text-[11px] font-medium text-[#753330]">Offline Mode</span>
              </>
            )}
          </button>

          {user.teamName && (
            <span className="hidden xl:inline-block text-xs text-[#626560] bg-[#F8F8F6] px-2.5 py-1 rounded-md border border-[#E5E5E0] font-normal">
              Team: <strong className="text-[#171817] font-semibold">{user.teamName}</strong>
            </span>
          )}
        </div>

        {/* Right: Actions */}
        <div className="flex items-center space-x-1.5 sm:space-x-2.5 shrink-0">
          {onOpenNewLead && (
            <button
              onClick={onOpenNewLead}
              className="h-8 sm:h-9 px-2.5 sm:px-3.5 rounded-xl bg-gradient-to-r from-[#B69A63] to-[#C6AD7A] hover:from-[#C6AD7A] hover:to-[#D2BE91] text-[#0B0C0D] font-bold text-xs uppercase tracking-wider shadow-xs flex items-center gap-1.5 transition active:scale-95 cursor-pointer shrink-0"
              title="Create New Lead"
            >
              <Plus className="w-4 h-4 stroke-[2.5]" />
              <span className="hidden sm:inline">New Lead</span>
            </button>
          )}

          {/* Mobile search icon */}
          <button
            onClick={() => setIsCommandPaletteOpen(true)}
            className="md:hidden p-2 rounded-xl text-[#626560] hover:text-[#171817] hover:bg-[#F8F8F6] transition cursor-pointer"
            aria-label="Search"
            title="Quick Search"
          >
            <Search className="w-4 h-4" />
          </button>

          {/* Real-Time Notifications Center Bell */}
          <button
            onClick={() => setIsDrawerOpen(true)}
            className="p-2 rounded-xl text-[#626560] hover:text-[#171817] hover:bg-[#F8F8F6] relative transition border border-transparent hover:border-[#E5E5E0] cursor-pointer shrink-0"
            aria-label="Notifications"
            title="Open Notification Center"
          >
            <Bell className="w-4 h-4" />
            {unreadCount > 0 && (
              <span className="absolute top-0.5 right-0.5 min-w-[15px] h-[15px] px-0.5 bg-rose-600 text-white text-[9px] font-black flex items-center justify-center rounded-full ring-2 ring-white">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          {/* User Identity Profile */}
          <div className="flex items-center space-x-1.5 sm:space-x-2 pl-1.5 sm:pl-3 border-l border-[#E5E5E0] shrink-0">
            <Link
              href="/dashboard/profile"
              prefetch={true}
              title="Manage Profile"
              className="flex items-center space-x-2 hover:opacity-85 transition group"
            >
              <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-[#111314] text-[#F4F2EC] font-bold flex items-center justify-center text-xs shadow-xs group-hover:ring-2 group-hover:ring-[#B69A63]/50 shrink-0">
                {user.name ? user.name.charAt(0).toUpperCase() : 'U'}
              </div>
              <div className="hidden sm:block text-left text-xs leading-tight">
                <p className="font-bold text-[#171817] truncate max-w-[120px] group-hover:text-[#B69A63]">
                  {user.name}
                </p>
                <p className="text-[10px] text-[#626560] truncate max-w-[120px] font-mono">
                  {user.role.replace('_', ' ')}
                </p>
              </div>
            </Link>

            <Link
              href="/dashboard/profile"
              prefetch={true}
              title="Manage Profile"
              className="hidden md:flex p-1.5 rounded-lg text-[#90928E] hover:text-[#171817] hover:bg-[#F8F8F6] transition cursor-pointer"
            >
              <User className="w-4 h-4" />
            </Link>

            <button
              onClick={handleLogout}
              disabled={isLoggingOut}
              title="Sign out of ORVION"
              className="p-1.5 rounded-lg text-[#90928E] hover:text-[#753330] hover:bg-[#F7EEED] transition cursor-pointer"
            >
              <LogOut className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Real-time Notification Center Drawer (Feature #4) */}
      <NotificationDrawer
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
        notifications={notifications}
        onRefresh={fetchNotifications}
      />

      {/* Command Palette Modal */}
      <CommandPalette
        user={user}
        isOpen={isCommandPaletteOpen}
        onClose={() => setIsCommandPaletteOpen(false)}
        onOpenNewLead={onOpenNewLead}
      />
    </header>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
  LayoutDashboard,
  Users,
  PhoneCall,
  Calendar,
  Layers,
  FolderKanban,
  FileSpreadsheet,
  ShieldCheck,
  BarChart3,
  Building2,
  Clock,
  PhoneOff,
  UserX,
  Share2,
  HelpCircle,
  TrendingUp,
  Sparkles,
  UploadCloud,
  Briefcase,
  DollarSign,
  UserPlus,
  User,
  Settings,
  X,
} from 'lucide-react';
import { UserRole } from '@/types';
import clsx from 'clsx';

interface SidebarProps {
  role: UserRole;
  userName?: string;
  isOpen?: boolean;
  onClose?: () => void;
}

interface NavLinkItem {
  label: string;
  href: string;
  icon: React.ComponentType<{ className?: string }>;
  highlight?: boolean;
}

interface NavSectionItem {
  section: string;
}

type NavItem = NavLinkItem | NavSectionItem;

export const Sidebar: React.FC<SidebarProps> = ({ role, isOpen = false, onClose }) => {
  const pathname = usePathname();
  const [optimisticPathname, setOptimisticPathname] = useState(pathname);

  // Synchronize optimistic state whenever route transition completes
  useEffect(() => {
    setOptimisticPathname(pathname);
  }, [pathname]);

  const adminNav: NavItem[] = [
    { label: 'Leads Dashboard', href: '/dashboard/admin/dashboard', icon: LayoutDashboard },
    { label: 'Calling Dashboard', href: '/dashboard/admin/calling', icon: PhoneCall, highlight: true },
    { label: 'Deals Pipeline (Kanban)', href: '/dashboard/admin/pipeline', icon: FolderKanban },
    { section: 'LEADS PIPELINE' },
    { label: 'All Leads', href: '/dashboard/admin/leads', icon: Layers },
    { label: 'Interested Leads', href: '/dashboard/admin/interested', icon: Sparkles },
    { label: 'Bulk Upload Hub', href: '/dashboard/admin/bulk-upload', icon: UploadCloud },
    { section: 'QUEUES & TRIAGE' },
    { label: 'Not Answering', href: '/dashboard/admin/not-answering', icon: PhoneOff },
    { label: 'Not Interested', href: '/dashboard/admin/not-interested', icon: UserX },
    { label: 'Channel Partners', href: '/dashboard/admin/channel-partners', icon: Share2 },
    { label: 'Other Leads', href: '/dashboard/admin/other', icon: HelpCircle },
    { section: 'MANAGEMENT' },
    { label: 'All Meetings', href: '/dashboard/meetings', icon: Calendar },
    { label: 'Team Structure', href: '/dashboard/admin/teams', icon: Building2 },
    { label: 'User Directory', href: '/dashboard/admin/users', icon: Users },
    { label: 'HR & Workforce', href: '/dashboard/hr/dashboard', icon: Briefcase },
    { label: 'Reports & Funnel', href: '/dashboard/reports', icon: BarChart3 },
    { label: 'Audit Logs', href: '/dashboard/admin/audit', icon: ShieldCheck },
    { label: 'Spreadsheet Sync', href: '/dashboard/admin/sync', icon: FileSpreadsheet },
  ];

  const hrNav: NavItem[] = [
    { label: 'HR Dashboard', href: '/dashboard/hr/dashboard', icon: LayoutDashboard },
    { label: 'Staff Directory', href: '/dashboard/hr/employees', icon: Users },
    { label: 'Attendance & Shifts', href: '/dashboard/hr/attendance', icon: Clock },
    { label: 'Leave Requests', href: '/dashboard/hr/leaves', icon: Calendar },
    { label: 'Targets & Payroll', href: '/dashboard/hr/payroll', icon: DollarSign },
    { label: 'Hiring Pipeline', href: '/dashboard/hr/recruitment', icon: UserPlus },
  ];

  const teamLeadNav: NavItem[] = [
    { label: 'Team Dashboard', href: '/dashboard/team-lead/dashboard', icon: LayoutDashboard },
    { label: "Today's Leads", href: '/dashboard/team-lead/today', icon: Clock },
    { label: 'Calling Data', href: '/dashboard/team-lead/calling', icon: PhoneCall },
    {
      label: 'VIEW TEAM WORKFLOW',
      href: '/dashboard/team-lead/workflow',
      icon: TrendingUp,
      highlight: true,
    },
    { label: 'Deals Pipeline', href: '/dashboard/admin/pipeline', icon: FolderKanban },
    { label: 'Team Meetings', href: '/dashboard/meetings', icon: Calendar },
    { label: 'Performance Reports', href: '/dashboard/reports', icon: BarChart3 },
  ];

  const executiveNav: NavItem[] = [
    { label: 'Dashboard', href: '/dashboard/executive/dashboard', icon: LayoutDashboard },
    { label: "Today's Leads", href: '/dashboard/executive/today', icon: Clock },
    { label: 'Calling Data', href: '/dashboard/executive/calling', icon: PhoneCall },
    { label: 'Leads Workspace', href: '/dashboard/executive/workspace', icon: FolderKanban },
    { label: 'Weekly Meetings', href: '/dashboard/meetings', icon: Calendar },
  ];

  const items =
    role === 'ADMIN' ? adminNav : role === 'TEAM_LEAD' ? teamLeadNav : role === 'HR' ? hrNav : executiveNav;

  const currentPath = (optimisticPathname || pathname || '').split('?')[0];

  const renderSidebarContent = (isMobile: boolean) => (
    <>
      {/* Brand Header */}
      <div
        className={clsx(
          'p-5 border-b border-[#1E2021] bg-[#0B0C0D] flex items-center justify-between',
          isMobile ? 'pt-[calc(1.25rem+env(safe-area-inset-top,0px))]' : ''
        )}
      >
        <div className="flex items-center space-x-3">
          <img
            src="/logo.png"
            alt="ORVION Logo"
            className="w-8 h-8 rounded-lg object-cover border border-[#B69A63]/50 shadow-xs ring-1 ring-[#B69A63]/20"
          />
          <div>
            <h1 className="text-sm font-black tracking-widest text-[#F4F2EC] uppercase">ORVION</h1>
            <p className="text-[10px] text-[#C6AD7A] font-semibold tracking-widest uppercase mt-0.5">ENTERPRISE CRM</p>
          </div>
        </div>

        {isMobile && (
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-[#8E918B] hover:text-[#F4F2EC] hover:bg-[#1E2021] transition cursor-pointer"
            title="Close menu"
          >
            <X className="w-5 h-5" />
          </button>
        )}
      </div>

      {/* Role Pill */}
      <div className="px-5 py-2.5 bg-[#111314] border-b border-[#1E2021] flex items-center justify-between">
        <span className="text-[11px] text-[#AEB1AC] font-medium tracking-wide">Access Scope</span>
        <span className="text-[10px] font-semibold px-2.5 py-0.5 rounded-full border bg-[#17191A] text-[#D2BE91] border-[#B69A63]/40 tracking-wider">
          {role.replace('_', ' ')}
        </span>
      </div>

      {/* Nav List */}
      <div className="flex-1 overflow-y-auto dark-scrollbar px-3 py-4 space-y-1">
        {items.map((item, idx) => {
          if ('section' in item) {
            return (
              <div
                key={idx}
                className="text-[10px] font-bold text-[#626560] tracking-widest px-3 pt-4 pb-1.5 uppercase font-mono"
              >
                {item.section}
              </div>
            );
          }

          const Icon = item.icon;
          const targetPath = item.href.split('?')[0];
          const isActive = currentPath === targetPath;
          const isHighlight = item.highlight;

          return (
            <Link
              key={item.href}
              href={item.href}
              prefetch={true}
              onPointerDown={() => setOptimisticPathname(item.href)}
              onClick={() => {
                setOptimisticPathname(item.href);
                if (isMobile && onClose) onClose();
              }}
              className={clsx(
                'flex items-center px-3 py-2 rounded-xl text-xs transition-all duration-100 relative group select-none active:scale-[0.98] cursor-pointer',
                isActive
                  ? 'bg-[#17191A] text-[#F4F2EC] border border-[#2A2D2E] font-semibold shadow-2xs'
                  : isHighlight
                  ? 'bg-[#17191A]/80 text-[#D2BE91] border border-[#B69A63]/40 font-semibold hover:bg-[#1E2021]'
                  : 'text-[#AEB1AC] hover:text-[#F4F2EC] hover:bg-[#141617]'
              )}
            >
              {/* Bronze active indicator */}
              {isActive && (
                <span className="w-1 h-3.5 bg-[#B69A63] rounded-full mr-2.5 shrink-0 shadow-[0_0_8px_rgba(182,154,99,0.5)]" />
              )}
              <Icon
                className={clsx(
                  'w-4 h-4 flex-shrink-0 mr-2.5 transition-colors',
                  isActive
                    ? 'text-[#B69A63]'
                    : isHighlight
                    ? 'text-[#C6AD7A]'
