import React, { useEffect, useState, useTransition } from 'react';
import { usePathname, useSearchParams } from 'next/navigation';

export const TopLoadingBar: React.FC = () => {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);

  // Whenever the route actually resolves, complete the loading animation
  useEffect(() => {
    if (loading) {
      setProgress(100);
      const timer = setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 200);
      return () => clearTimeout(timer);
    }
  }, [pathname, searchParams]);

  // Global click interceptor for instant 0ms navigation feedback
  useEffect(() => {
    const handleDocumentClick = (e: MouseEvent) => {
      const target = (e.target as HTMLElement)?.closest('a');
      if (!target) return;

      const href = target.getAttribute('href');
      const targetAttr = target.getAttribute('target');

      // Only trigger for internal links that aren't open-in-new-tab or anchors
      if (
        href &&
        href.startsWith('/') &&
        !href.startsWith('//') &&
        targetAttr !== '_blank' &&
        !e.ctrlKey &&
        !e.metaKey &&
        !e.shiftKey
      ) {
        // If clicking current route, don't trigger
        const currentFull = window.location.pathname + window.location.search;
        if (href === currentFull) return;

        setLoading(true);
        setProgress(25);

        // Advance progress smoothly while waiting
        const t1 = setTimeout(() => setProgress(65), 80);
        const t2 = setTimeout(() => setProgress(85), 250);

        // Safety fallback: if route does not change in 4s, hide bar
        const safetyTimer = setTimeout(() => {
          setLoading(false);
          setProgress(0);
        }, 4000);

        return () => {
          clearTimeout(t1);
          clearTimeout(t2);
          clearTimeout(safetyTimer);
        };
      }
    };

    document.addEventListener('click', handleDocumentClick, true);
    return () => {
      document.removeEventListener('click', handleDocumentClick, true);
    };
  }, []);

  if (!loading && progress === 0) return null;

  return (
    <div
      className="fixed top-0 left-0 right-0 z-50 pointer-events-none h-[2.5px] bg-transparent"
      aria-hidden="true"
    >
      <div
        className="h-full bg-gradient-to-r from-[#B69A63] via-[#D2BE91] to-[#F4F2EC] shadow-[0_0_10px_rgba(182,154,99,0.8)] transition-all duration-200 ease-out"
        style={{
          width: `${progress}%`,
          opacity: progress === 100 ? 0 : 1,
          transition: progress === 100 ? 'width 150ms ease-out, opacity 200ms ease-out' : 'width 200ms ease-out',
        }}
      />
    </div>
  );
};

'use client';

import React, { useState } from 'react';
import {
  Trash2,
  RefreshCw,
  Tag,
  Download,
  X,
  AlertTriangle,
  CheckCircle2,
  Users,
  Layers,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { emitCrmSync } from '@/lib/sync-event';
import { invalidateFastCache } from '@/lib/fast-data';
import { generateCSV, downloadCSV, ExportColumn } from '@/lib/export-utils';

export interface BulkActionBarProps {
  selectedIds: string[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  selectedLeads?: any[];
  onClearSelection: () => void;
  onSuccess: () => void;
  executives?: Array<{ id: string; name: string }>;
  canDelete?: boolean;
  canReassign?: boolean;
}

export const BulkActionBar: React.FC<BulkActionBarProps> = ({
  selectedIds,
  selectedLeads = [],
  onClearSelection,
  onSuccess,
  executives = [],
  canDelete = true,
  canReassign = true,
}) => {
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isReassignModalOpen, setIsReassignModalOpen] = useState(false);
  const [isStatusModalOpen, setIsStatusModalOpen] = useState(false);

  // Reassign form state
  const [newOwnerId, setNewOwnerId] = useState('');
  const [reassignReason, setReassignReason] = useState('Bulk Reassignment');

  // Status form state
  const [newStatus, setNewStatus] = useState('INTERESTED');
  const [statusRemark, setStatusRemark] = useState('');

  // Processing states
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (selectedIds.length === 0) return null;

  const count = selectedIds.length;

  const handleBulkDelete = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/leads/bulk-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'DELETE',
          ids: selectedIds,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || 'Failed to delete leads');
      }

      invalidateFastCache();
      emitCrmSync('leads');
      emitCrmSync('calling');
      emitCrmSync('all');
      setIsDeleteModalOpen(false);
      onClearSelection();
      onSuccess();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Error deleting leads');
    } finally {
      setLoading(false);
    }
  };

  const handleBulkReassign = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/leads/bulk-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'REASSIGN',
          ids: selectedIds,
          newOwnerId: newOwnerId || null,
          reason: reassignReason,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || 'Failed to reassign leads');
      }

      invalidateFastCache();
      emitCrmSync('leads');
      emitCrmSync('calling');
      emitCrmSync('all');
      setIsReassignModalOpen(false);
      onClearSelection();
      onSuccess();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Error reassigning leads');
    } finally {
      setLoading(false);
    }
  };

  const handleBulkStatusUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/leads/bulk-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'STATUS_UPDATE',
          ids: selectedIds,
          status: newStatus,
          remark: statusRemark || `Bulk updated to ${newStatus}`,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || 'Failed to update lead status');
      }

      invalidateFastCache();
      emitCrmSync('leads');
      emitCrmSync('calling');
      emitCrmSync('all');
      setIsStatusModalOpen(false);
      onClearSelection();
      onSuccess();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Error updating leads');
    } finally {
      setLoading(false);
    }
  };

  const handleExportSelected = () => {
    if (selectedLeads.length === 0) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const columns: ExportColumn<any>[] = [
      { header: 'Lead Number', accessor: (l) => l.leadNumber },
      { header: 'Client Name', accessor: (l) => l.clientName },
      { header: 'Phone', accessor: (l) => l.phone },
      { header: 'Company', accessor: (l) => l.company || 'N/A' },
      { header: 'Source', accessor: (l) => l.source },
      { header: 'Status', accessor: (l) => l.currentStatus },
      { header: 'Category', accessor: (l) => l.currentCategory },
      { header: 'Owner', accessor: (l) => l.currentOwner?.name || 'Unassigned' },
      { header: 'Next Action', accessor: (l) => l.nextAction || 'None' },
      {
        header: 'Next Action Due',
        accessor: (l) => (l.nextActionAt ? new Date(l.nextActionAt).toLocaleString() : 'None'),
      },
    ];
    const csv = generateCSV(selectedLeads, columns);
    downloadCSV(`orvion_selected_${count}_leads_${new Date().toISOString().slice(0, 10)}.csv`, csv);
  };

  return (
    <>
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 max-w-2xl w-[92%] bg-[#171817]/95 backdrop-blur-md text-white px-4 py-3 rounded-2xl shadow-2xl border border-white/10 flex flex-wrap items-center justify-between gap-3 animate-in fade-in slide-in-from-bottom-4 duration-200">
        <div className="flex items-center gap-2.5">
          <span className="flex items-center justify-center w-6 h-6 rounded-full bg-[#B69A63] text-black text-xs font-bold font-mono">
            {count}
          </span>
          <span className="text-xs font-semibold tracking-wide">
            {count} {count === 1 ? 'lead' : 'leads'} selected
