'use client';

import React, { useState, useMemo } from 'react';
import Link from 'next/link';
import {
  User,
  Phone,
  MessageSquare,
  DollarSign,
  Calendar,
  ChevronRight,
  TrendingUp,
  Search,
  Filter,
  CheckCircle2,
  AlertCircle,
  MoreVertical,
  Flame,
  ArrowRight,
  ExternalLink,
  Zap,
} from 'lucide-react';
import { LeadTemperatureBadge } from '../leads/LeadTemperatureBadge';
import { WhatsAppModal } from '../leads/WhatsAppModal';
import { emitCrmSync } from '@/lib/sync-event';

export interface PipelineLead {
  id: string;
  leadNumber: string;
  clientName: string;
  phone: string;
  source: string;
  currentStatus: string;
  currentCategory: string;
  score?: number | null;
  temperature?: string | null;
  estimatedValue?: number | null;
  nextAction?: string | null;
  nextActionAt?: string | null;
  createdAt: string;
  currentOwner?: {
    id: string;
    name: string;
    email: string;
  } | null;
}

interface KanbanBoardProps {
  leads: PipelineLead[];
  onRefresh: () => void;
  isAdmin?: boolean;
}

interface ColumnDef {
  id: string;
  title: string;
  color: string;
  badgeBg: string;
  statuses: string[];
}

const COLUMNS: ColumnDef[] = [
  {
    id: 'NEW',
    title: 'New Inquiries',
    color: 'border-blue-400',
    badgeBg: 'bg-blue-50 text-blue-700 border-blue-200',
    statuses: ['NEW'],
  },
  {
    id: 'CONTACTED',
    title: 'Contacted & Follow-up',
    color: 'border-amber-400',
    badgeBg: 'bg-amber-50 text-amber-700 border-amber-200',
    statuses: ['INTERESTED', 'FOLLOW_UP', 'CALL_BACK'],
  },
  {
    id: 'MEETING',
    title: 'Site Visit / Meeting',
    color: 'border-purple-400',
    badgeBg: 'bg-purple-50 text-purple-700 border-purple-200',
    statuses: ['MEETING', 'SITE_VISIT'],
  },
  {
    id: 'NEGOTIATION',
    title: 'Quotation & Negotiation',
    color: 'border-indigo-400',
    badgeBg: 'bg-indigo-50 text-indigo-700 border-indigo-200',
    statuses: ['QUOTATION', 'NEGOTIATION'],
  },
  {
    id: 'CLOSED_WON',
    title: 'Closed Won',
    color: 'border-emerald-500',
    badgeBg: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    statuses: ['CLOSED_WON'],
  },
  {
    id: 'LOST_OTHER',
    title: 'Lost / NA / Other',
    color: 'border-zinc-400',
    badgeBg: 'bg-zinc-100 text-zinc-700 border-zinc-200',
    statuses: ['CLOSED_LOST', 'NOT_INTERESTED', 'NOT_ANSWERING', 'OTHER', 'CHANNEL_PARTNER'],
  },
];

export const KanbanBoard: React.FC<KanbanBoardProps> = ({
  leads,
  onRefresh,
  isAdmin = true,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedOwner, setSelectedOwner] = useState<string>('ALL');
  const [selectedTemp, setSelectedTemp] = useState<string>('ALL');
  const [whatsAppLead, setWhatsAppLead] = useState<PipelineLead | null>(null);
  const [movingLeadId, setMovingLeadId] = useState<string | null>(null);

  // Extract unique executives
  const uniqueOwners = useMemo(() => {
    const ownersMap = new Map<string, string>();
    leads.forEach((l) => {
      if (l.currentOwner) {
        ownersMap.set(l.currentOwner.id, l.currentOwner.name);
      }
    });
    return Array.from(ownersMap.entries()).map(([id, name]) => ({ id, name }));
  }, [leads]);

  // Filter leads
  const filteredLeads = useMemo(() => {
    return leads.filter((lead) => {
      if (
        searchQuery &&
        !lead.clientName.toLowerCase().includes(searchQuery.toLowerCase()) &&
        !lead.phone.includes(searchQuery) &&
        !lead.leadNumber.toLowerCase().includes(searchQuery.toLowerCase())
      ) {
        return false;
      }
      if (selectedOwner !== 'ALL') {
        if (selectedOwner === 'UNASSIGNED' && lead.currentOwner) return false;
        if (selectedOwner !== 'UNASSIGNED' && lead.currentOwner?.id !== selectedOwner)
          return false;
      }
      if (selectedTemp !== 'ALL' && lead.temperature !== selectedTemp) {
        return false;
      }
      return true;
    });
  }, [leads, searchQuery, selectedOwner, selectedTemp]);

  // Group leads into columns
  const columnData = useMemo(() => {
    return COLUMNS.map((col) => {
      const colLeads = filteredLeads.filter((l) =>
        col.statuses.includes(l.currentStatus)
      );
      const totalValue = colLeads.reduce(
        (sum, l) => sum + (l.estimatedValue || 0),
        0
      );
      return {
        ...col,
        leads: colLeads,
        totalValue,
      };
    });
  }, [filteredLeads]);

  const totalPipelineValue = useMemo(() => {
    return filteredLeads.reduce((sum, l) => sum + (l.estimatedValue || 0), 0);
  }, [filteredLeads]);

  const formatCurrency = (val: number) => {
    if (val >= 10000000) {
      return `₹${(val / 10000000).toFixed(2)} Cr`;
    }
    if (val >= 100000) {
      return `₹${(val / 100000).toFixed(2)} L`;
    }
    return `₹${val.toLocaleString('en-IN')}`;
  };

  const handleStageChange = async (leadId: string, newStatus: string) => {
    setMovingLeadId(leadId);
    try {
      const res = await fetch(`/api/leads/${leadId}/stage`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          status: newStatus,
          reason: `Pipeline stage changed to ${newStatus}`,
        }),
      });

      if (res.ok) {
        emitCrmSync('leads');
        onRefresh();
      }
    } catch (err) {
      console.error('Failed to change stage:', err);
    } finally {
      setMovingLeadId(null);
    }
  };

  return (
    <div className="space-y-4">
      {/* Top Filter & Metric Bar */}
      <div className="bg-white p-4 rounded-xl border border-[#E5E5E0] shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
        {/* Left Filters */}
        <div className="flex flex-wrap items-center gap-3">
          {/* Search */}
          <div className="relative min-w-[220px]">
            <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Filter deals..."
              className="w-full pl-9 pr-3 py-1.5 bg-[#FBFBFA] border border-[#E5E5E0] rounded-lg text-xs text-[#171817] outline-none focus:border-[#B69A63]"
            />
          </div>

          {/* Executive Filter */}
          <select
            value={selectedOwner}
            onChange={(e) => setSelectedOwner(e.target.value)}
            className="px-3 py-1.5 bg-[#FBFBFA] border border-[#E5E5E0] rounded-lg text-xs text-[#171817] outline-none focus:border-[#B69A63]"
          >
            <option value="ALL">All Executives</option>
            <option value="UNASSIGNED">Unassigned Pool</option>
            {uniqueOwners.map((o) => (
              <option key={o.id} value={o.id}>
                {o.name}
              </option>
            ))}
          </select>

          {/* Temperature Filter */}
          <select
            value={selectedTemp}
            onChange={(e) => setSelectedTemp(e.target.value)}
            className="px-3 py-1.5 bg-[#FBFBFA] border border-[#E5E5E0] rounded-lg text-xs text-[#171817] outline-none focus:border-[#B69A63]"
          >
            <option value="ALL">All Temperatures</option>
            <option value="HOT">🔥 HOT</option>
            <option value="WARM">☀️ WARM</option>
            <option value="COLD">❄️ COLD</option>
          </select>
        </div>

        {/* Right Total Metric */}
        <div className="flex items-center gap-4 shrink-0">
          <div className="text-right">
            <span className="text-[11px] text-[#626560] font-medium block">
              Total Pipeline Value
            </span>
            <span className="text-base font-bold text-[#171817] tracking-tight text-[#B69A63]">
              {formatCurrency(totalPipelineValue)}
            </span>
          </div>
          <div className="h-8 w-px bg-zinc-200" />
          <div className="text-right">
            <span className="text-[11px] text-[#626560] font-medium block">
              Active Deals
            </span>
            <span className="text-base font-bold text-[#171817]">
              {filteredLeads.length}
            </span>
          </div>
        </div>
      </div>

      {/* Kanban Columns: fixed-width columns inside an explicit horizontal scroller */}
      <div className="w-full overflow-x-auto overflow-y-hidden pb-4">
        <div className="flex min-w-max items-start gap-4">
          {columnData.map((col) => (
            <div
              key={col.id}
              className="w-[270px] shrink-0 bg-[#F8F8F6] rounded-xl border border-[#E5E5E0] flex flex-col max-h-[calc(100vh-250px)]"
            >
            {/* Column Header */}
            <div
              className={`p-3 border-b border-[#E5E5E0] bg-white rounded-t-xl border-t-4 ${col.color}`}
            >
              <div className="flex items-center justify-between">
                <span className="font-bold text-xs text-[#171817] truncate">
                  {col.title}
                </span>
                <span
                  className={`text-[11px] font-bold px-2 py-0.5 rounded-full border ${col.badgeBg}`}
                >
                  {col.leads.length}
                </span>
              </div>
              <div className="mt-1 text-[11px] font-semibold text-[#8C9089]">
                {formatCurrency(col.totalValue)}
              </div>
            </div>

            {/* Column Cards List */}
            <div className="p-2 space-y-2.5 overflow-y-auto flex-1">
              {col.leads.length === 0 ? (
                <div className="py-8 text-center text-xs text-zinc-400 border border-dashed border-zinc-200 rounded-lg">
                  No deals in this stage
                </div>
              ) : (
                col.leads.map((lead) => (
                  <div
                    key={lead.id}
                    className={`bg-white p-3 rounded-lg border border-[#E5E5E0] shadow-sm hover:shadow-md transition-all ${
                      movingLeadId === lead.id ? 'opacity-50 pointer-events-none' : ''
                    }`}
                  >
                    {/* Top Row: Lead Number & Temp */}
                    <div className="flex items-center justify-between text-[11px] mb-1.5">
                      <span className="font-mono text-zinc-500 font-semibold">
                        {lead.leadNumber}
                      </span>
                      <LeadTemperatureBadge
                        score={lead.score || 50}
                        temperature={lead.temperature || 'WARM'}
                      />
                    </div>

                    {/* Client Name & Phone */}
                    <Link
                      href={
                        isAdmin
                          ? `/dashboard/leads/${lead.id}`
                          : `/dashboard/executive/workspace?leadId=${lead.id}`
                      }
                      prefetch={true}
                      className="font-bold text-sm text-[#171817] hover:text-[#B69A63] transition-colors block truncate"
                    >
                      {lead.clientName}
                    </Link>

                    <div className="text-xs text-zinc-500 mt-0.5 flex items-center justify-between">
                      <span>{lead.phone}</span>
                      {lead.estimatedValue ? (
                        <span className="font-bold text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-100 text-[10px]">
                          {formatCurrency(lead.estimatedValue)}
                        </span>
                      ) : null}
                    </div>

                    {/* Owner & Next Action */}
                    <div className="mt-2 pt-2 border-t border-zinc-100 flex items-center justify-between text-[11px] text-zinc-500">
                      <span className="truncate max-w-[120px]">
                        👤 {lead.currentOwner ? lead.currentOwner.name : 'Unassigned'}
                      </span>
                      {lead.nextActionAt && (
                        <span className="text-amber-700 font-medium shrink-0">
                          📅 {new Date(lead.nextActionAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                        </span>
                      )}
                    </div>

                    {/* Stage Move Dropdown & Quick Actions */}
                    <div className="mt-2.5 pt-2 border-t border-zinc-100 flex items-center justify-between gap-1.5">
                      <select
                        value={lead.currentStatus}
                        onChange={(e) => handleStageChange(lead.id, e.target.value)}
                        className="text-[10px] font-semibold bg-zinc-50 border border-zinc-200 rounded px-1.5 py-1 text-zinc-700 outline-none hover:bg-zinc-100 w-full"
                      >
                        <option value="NEW">Stage: NEW</option>
                        <option value="INTERESTED">Stage: INTERESTED</option>
                        <option value="FOLLOW_UP">Stage: FOLLOW UP</option>
                        <option value="CALL_BACK">Stage: CALL BACK</option>
                        <option value="MEETING">Stage: MEETING</option>
                        <option value="SITE_VISIT">Stage: SITE VISIT</option>
                        <option value="QUOTATION">Stage: QUOTATION</option>
                        <option value="NEGOTIATION">Stage: NEGOTIATION</option>
                        <option value="CLOSED_WON">Stage: CLOSED WON</option>
                        <option value="CLOSED_LOST">Stage: CLOSED LOST</option>
                        <option value="NOT_ANSWERING">Stage: NOT ANSWERING</option>
                      </select>

                      {/* WhatsApp trigger */}
                      <button
                        onClick={() => setWhatsAppLead(lead)}
                        className="p-1 rounded text-emerald-600 hover:bg-emerald-50 transition-colors shrink-0"
                        title="Send WhatsApp"
                      >
                        <MessageSquare className="w-3.5 h-3.5" />
                      </button>

                      {/* Phone trigger */}
                      <a
                        href={`tel:${lead.phone}`}
                        className="p-1 rounded text-blue-600 hover:bg-blue-50 transition-colors shrink-0"
                        title="Call"
                      >
                        <Phone className="w-3.5 h-3.5" />
                      </a>
                    </div>
                  </div>
                ))
              )}
            </div>
            </div>
          ))}
        </div>
      </div>

      {/* WhatsApp Modal */}
      {whatsAppLead && (
        <WhatsAppModal
          isOpen={true}
          onClose={() => setWhatsAppLead(null)}
          leadId={whatsAppLead.id}
          clientName={whatsAppLead.clientName}
          phone={whatsAppLead.phone}
          senderName="Orvion Executive"
        />
      )}
    </div>
  );
};

'use client';

import React, { useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { emitCrmSync } from '@/lib/sync-event';
import { invalidateFastCache } from '@/lib/fast-data';

interface RealtimeSyncProviderProps {
  children?: React.ReactNode;
}

export const RealtimeSyncProvider: React.FC<RealtimeSyncProviderProps> = ({ children }) => {
  const router = useRouter();
  const lastPulseKeyRef = useRef<string | null>(null);
  const isFirstCheckRef = useRef<boolean>(true);
  const isCheckingRef = useRef<boolean>(false);

  const checkPulse = async () => {
    if (isCheckingRef.current) return;
    isCheckingRef.current = true;

    try {
      const res = await fetch(`/api/sync/pulse?_t=${Date.now()}`, {
        cache: 'no-store',
        headers: { 'Cache-Control': 'no-cache' },
      });

      if (res.ok) {
        const data = await res.json();
        const currentPulse = data.pulseKey;

        if (lastPulseKeyRef.current === null) {
          lastPulseKeyRef.current = currentPulse;
          isFirstCheckRef.current = false;
        } else if (lastPulseKeyRef.current !== currentPulse) {
          lastPulseKeyRef.current = currentPulse;

          // Data changed on server (e.g. bulk upload, new lead assigned, status updated)
          // 1. Invalidate stale client caches
          invalidateFastCache();

          // 2. Broadcast local sync event to all active reactive views
          emitCrmSync('all', data);
        }
      }
    } catch {
      // silent background failure
    } finally {
      isCheckingRef.current = false;
    }
  };

  useEffect(() => {
    // Initial pulse check
    checkPulse();

    // Fast high-frequency heartbeat (4 seconds)
    const interval = setInterval(() => {
      if (typeof document !== 'undefined' && document.hidden) {
        // Lower frequency when tab is in background to save battery/bandwidth
        return;
      }
      checkPulse();
    }, 4000);

    // Background tab low-frequency heartbeat (8 seconds)
    const bgInterval = setInterval(() => {
      if (typeof document !== 'undefined' && document.hidden) {
        checkPulse();
      }
    }, 8000);

    // Instant check when executive switches back to tab or device unlocks
    const handleFocus = () => checkPulse();
    const handleVisibility = () => {
      if (typeof document !== 'undefined' && !document.hidden) {
        checkPulse();
      }
    };

    window.addEventListener('focus', handleFocus);
    window.addEventListener('online', handleFocus);
    document.addEventListener('visibilitychange', handleVisibility);

    return () => {
      clearInterval(interval);
      clearInterval(bgInterval);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('online', handleFocus);
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, []);

  return <>{children}</>;
};

'use client';

import React, { useState, useEffect } from 'react';
import {
  Sparkles,
  Plus,
  CheckCircle2,
  Clock,
  AlertTriangle,
  Users,
  Trash2,
  RefreshCw,
  Flame,
} from 'lucide-react';
import { AssignTaskModal } from './AssignTaskModal';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { useCrmSync, emitCrmSync } from '@/lib/sync-event';

interface TaskRecord {
  id: string;
  title: string;
  description?: string | null;
  priority: string;
  dueDate: string;
  dueTime: string;
  status: string;
  completedAt?: string | null;
  assignee: {
    id: string;
    name: string;
    email: string;
    designation?: string | null;
  };
  createdBy: {
    id: string;
    name: string;
    role: string;
  };
}

interface TasksOverviewData {
  tasks: TaskRecord[];
  stats: {
    total: number;
    completed: number;
    overdue: number;
    pending: number;
    completionRate: number;
  };
}

import { getFastCache, setFastCache } from '@/lib/fast-data';

interface AdminTasksOverviewWidgetProps {
  role?: 'ADMIN' | 'HR';
}

export const AdminTasksOverviewWidget: React.FC<AdminTasksOverviewWidgetProps> = ({
  role = 'ADMIN',
}) => {
  const cacheKey = `crm:tasks:overview:${role}`;

  const [data, setData] = useState<TasksOverviewData | null>(null);
  const [loading, setLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [taskToDelete, setTaskToDelete] = useState<TaskRecord | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const fetchTasksData = async (isBackground: boolean | unknown = false) => {
    const isBg = isBackground === true;
    const cached = getFastCache<TasksOverviewData>(cacheKey);
    if (!cached && !isBg) {
      setLoading(true);
    }
    try {
      const res = await fetch('/api/tasks');
      const json = await res.json();
      if (json.tasks) {
        setData(json);
        setFastCache(cacheKey, json, 60000);
      }
    } catch (err) {
      console.error('Failed to fetch tasks overview:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const cached = getFastCache<TasksOverviewData>(cacheKey);
    if (cached) {
      setData(cached);
      setLoading(false);
      fetchTasksData(true);
    } else {
      fetchTasksData(false);
    }
  }, []);

  useCrmSync(['tasks', 'all'], () => {
    fetchTasksData(true);
  });

  const handleConfirmDeleteTask = async () => {
    if (!taskToDelete) return;
    setIsDeleting(true);
    try {
      const res = await fetch(`/api/tasks/${taskToDelete.id}`, { method: 'DELETE' });
      if (res.ok) {
        emitCrmSync('tasks');
        setTaskToDelete(null);
        fetchTasksData(true);
      }
    } catch (err) {
      console.error('Error deleting task:', err);
    } finally {
      setIsDeleting(false);
    }
  };

  const formatDueTime = (timeStr: string) => {
    if (!timeStr) return '';
    const [hours, minutes] = timeStr.split(':').map(Number);
    if (isNaN(hours)) return timeStr;
    const period = hours >= 12 ? 'PM' : 'AM';
    const formattedHours = hours % 12 === 0 ? 12 : hours % 12;
    return `${formattedHours}:${String(minutes).padStart(2, '0')} ${period}`;
  };

  const stats = data?.stats || {
    total: 0,
    completed: 0,
    overdue: 0,
    pending: 0,
    completionRate: 0,
  };

  return (
    <div className="rounded-2xl bg-white border border-[#E5E5E0] shadow-xs overflow-hidden">
      {/* Header Banner */}
      <div className="p-4 sm:p-5 border-b border-[#E5E5E0] bg-[#FCFCFA] flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-[#111314] text-[#D2BE91] flex items-center justify-center shadow-xs">
            <Sparkles className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-sm font-bold text-[#171817]">
                Executive Daily Tasks & Completion Tracker
              </h3>
              <span className="px-2 py-0.5 rounded-md text-[10px] font-bold bg-[#F4F4F1] text-[#626560] border border-[#E5E5E0]">
                {role === 'HR' ? 'HR Workforce' : 'Admin Control'}
              </span>
            </div>
            <p className="text-xs text-[#626560] mt-0.5">
              Directives assigned to all executives or specific team members with daily completion deadlines.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={fetchTasksData}
            disabled={loading}
            title="Refresh"
            className="p-2 rounded-xl text-[#90928E] hover:text-[#171817] hover:bg-[#F4F4F1] transition border border-[#E5E5E0] cursor-pointer"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          </button>
          <Button
            onClick={() => setIsModalOpen(true)}
            className="text-xs px-3.5 py-1.5 bg-[#111314] hover:bg-[#1E2021] text-[#F4F2EC] border border-[#252829] font-semibold inline-flex items-center gap-1.5 transition cursor-pointer shadow-xs"
          >
            <Plus className="w-3.5 h-3.5 text-[#D2BE91]" /> Assign Executive Task
          </Button>
        </div>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 divide-x divide-[#E5E5E0] border-b border-[#E5E5E0] bg-white">
        <div className="p-3.5 text-center">
          <p className="text-[11px] font-semibold text-[#626560] flex items-center justify-center gap-1">
            <Users className="w-3 h-3 text-[#B69A63]" /> Total Assigned Today
          </p>
          <p className="text-xl font-black text-[#171817] mt-1">{stats.total}</p>
        </div>

        <div className="p-3.5 text-center">
          <p className="text-[11px] font-semibold text-[#2D5A3C] flex items-center justify-center gap-1">
            <CheckCircle2 className="w-3 h-3 text-[#2D5A3C]" /> Completed
          </p>
          <p className="text-xl font-black text-[#2D5A3C] mt-1">{stats.completed}</p>
        </div>

        <div className="p-3.5 text-center">
          <p className="text-[11px] font-semibold text-[#7A5B28] flex items-center justify-center gap-1">
            <Clock className="w-3 h-3 text-[#B69A63]" /> Pending
          </p>
          <p className="text-xl font-black text-[#171817] mt-1">{stats.pending}</p>
        </div>

        <div className="p-3.5 text-center">
          <p className="text-[11px] font-semibold text-[#B42318] flex items-center justify-center gap-1">
            <AlertTriangle className="w-3 h-3 text-[#B42318]" /> Overdue
          </p>
          <p className="text-xl font-black text-[#B42318] mt-1">{stats.overdue}</p>
        </div>
      </div>

      {/* Tasks Table / List */}
      <div className="overflow-x-auto">
        {loading && !data ? (
          <div className="p-8 text-center text-xs text-[#626560]">Loading tasks...</div>
        ) : !data || data.tasks.length === 0 ? (
          <div className="p-8 text-center">
            <p className="text-xs font-bold text-[#171817]">No Tasks Assigned Today</p>
            <p className="text-[11px] text-[#626560] mt-1">
              Click &ldquo;Assign Executive Task&rdquo; to broadcast a daily target or instruct a specific executive.
            </p>
          </div>
        ) : (
          <table className="w-full text-left text-xs">
            <thead className="bg-[#F8F8F6] text-[#626560] border-b border-[#E5E5E0] font-semibold">
              <tr>
                <th className="py-2.5 px-4">Executive</th>
                <th className="py-2.5 px-4">Task Directive</th>
                <th className="py-2.5 px-4">Priority</th>
                <th className="py-2.5 px-4">Deadline</th>
                <th className="py-2.5 px-4">Status</th>
                <th className="py-2.5 px-4">Assigned By</th>
                <th className="py-2.5 px-4 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#E5E5E0]">
              {data.tasks.map((task) => {
                const isOverdue = task.status === 'OVERDUE';
                const isCompleted = task.status === 'COMPLETED';

                return (
                  <tr key={task.id} className="hover:bg-[#FAFAF9] transition">
                    <td className="py-3 px-4 font-semibold text-[#171817]">
                      {task.assignee.name}
                      <span className="block text-[10px] font-normal text-[#90928E]">
                        {task.assignee.email}
                      </span>
                    </td>

                    <td className="py-3 px-4 max-w-xs">
                      <p className="font-semibold text-[#171817] truncate">{task.title}</p>
                      {task.description && (
                        <p className="text-[11px] text-[#626560] truncate mt-0.5">
                          {task.description}
                        </p>
                      )}
                    </td>

                    <td className="py-3 px-4">
                      {task.priority === 'HIGH' ? (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-[#FFF1F0] text-[#B42318] border border-[#FECDCA]">
                          <Flame className="w-3 h-3 text-[#B42318]" /> High
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium bg-[#F4F4F1] text-[#626560] border border-[#E5E5E0]">
                          Normal
                        </span>
                      )}
                    </td>

                    <td className="py-3 px-4 text-[#171817] font-medium">
                      {formatDueTime(task.dueTime)}
                    </td>

                    <td className="py-3 px-4">
                      {isCompleted ? (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-[#EDF5F0] text-[#2D5A3C] border border-[#D3E5D9]">
                          <CheckCircle2 className="w-3 h-3 text-[#2D5A3C]" /> Completed
                        </span>
                      ) : isOverdue ? (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-[#FFF1F0] text-[#B42318] border border-[#FECDCA]">
                          <AlertTriangle className="w-3 h-3 text-[#B42318]" /> Overdue
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-medium bg-[#FDF8EE] text-[#7A5B28] border border-[#EAD9B8]">
                          <Clock className="w-3 h-3 text-[#B69A63]" /> Pending
                        </span>
                      )}
                    </td>

                    <td className="py-3 px-4 text-[#626560] text-[11px]">
                      {task.createdBy.role === 'HR' ? 'HR' : 'Admin'} ({task.createdBy.name})
                    </td>

                    <td className="py-3 px-4 text-right">
                      <button
                        onClick={() => setTaskToDelete(task)}
                        title="Delete Task"
                        className="p-1 rounded-lg text-[#90928E] hover:text-[#B42318] hover:bg-[#FFF1F0] transition cursor-pointer"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Modal */}
      <AssignTaskModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSuccess={fetchTasksData}
      />

      {/* Delete Confirmation Modal */}
      {taskToDelete && (
        <Modal
          isOpen={true}
          onClose={() => setTaskToDelete(null)}
          title="Cancel & Delete Task"
        >
          <div className="space-y-4">
            <div className="flex items-start gap-3 p-3.5 bg-red-50 border border-red-200 rounded-xl text-red-900">
              <AlertTriangle className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
              <div className="text-xs space-y-1">
                <p className="font-bold text-sm">
                  Cancel task &ldquo;{taskToDelete.title}&rdquo;?
                </p>
                <p className="text-red-700">
                  This task assigned to <strong className="text-red-900">{taskToDelete.assignee.name}</strong> will be permanently removed from their daily checklist.
                </p>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-2 border-t border-[#E5E5E0]">
              <Button
                type="button"
                variant="secondary"
                onClick={() => setTaskToDelete(null)}
                disabled={isDeleting}
              >
                Keep Task
              </Button>
              <Button
                type="button"
                variant="danger"
                onClick={handleConfirmDeleteTask}
                isLoading={isDeleting}
              >
                Delete Task
              </Button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  Users,
  User,
  AlertCircle,
  Clock,
  Calendar,
  Sparkles,
  AlertTriangle,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';

interface AssignTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

interface ExecutiveUser {
  id: string;
  name: string;
  email: string;
  designation?: string | null;
}

export const AssignTaskModal: React.FC<AssignTaskModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const [target, setTarget] = useState<'ALL' | 'SPECIFIC'>('ALL');
  const [executives, setExecutives] = useState<ExecutiveUser[]>([]);
  const [selectedExecutiveId, setSelectedExecutiveId] = useState<string>('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<'HIGH' | 'NORMAL' | 'LOW'>('NORMAL');

  const todayStr = new Date().toISOString().split('T')[0];
  const [dueDate, setDueDate] = useState(todayStr);
  const [dueTime, setDueTime] = useState('18:00');

  const [loading, setLoading] = useState(false);
  const [fetchingUsers, setFetchingUsers] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      setError(null);
      setSuccessMsg(null);
      // Fetch active executives
      setFetchingUsers(true);
      fetch('/api/users?role=EXECUTIVE')
        .then((res) => res.json())
        .then((data) => {
          if (data.users && Array.isArray(data.users)) {
            setExecutives(data.users);
            if (data.users.length > 0 && !selectedExecutiveId) {
              setSelectedExecutiveId(data.users[0].id);
            }
          }
        })
        .catch((err) => console.error('Error fetching executives:', err))
        .finally(() => setFetchingUsers(false));
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMsg(null);

    if (!title.trim()) {
      setError('Please enter a task title');
      return;
    }

    if (target === 'SPECIFIC' && !selectedExecutiveId) {
      setError('Please select an executive');
      return;
    }

    setLoading(true);
    try {
      const res = await fetch('/api/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: title.trim(),
          description: description.trim() || undefined,
          priority,
          target,
          assigneeId: target === 'SPECIFIC' ? selectedExecutiveId : undefined,
          dueDate,
          dueTime,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to assign task');
      }

      setSuccessMsg(
        target === 'ALL'
          ? `Daily task broadcasted to ${data.count || 'all'} active executives!`
          : `Task successfully assigned!`
      );

      setTimeout(() => {
        setTitle('');
        setDescription('');
        setPriority('NORMAL');
        setDueDate(todayStr);
        setDueTime('18:00');
        onSuccess?.();
        onClose();
      }, 1200);
    } catch (err: any) {
      setError(err.message || 'An error occurred while creating task');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/60 backdrop-blur-xs transition-opacity"
        onClick={onClose}
      />

      {/* Modal Surface */}
      <div className="relative w-full max-w-lg rounded-2xl bg-white border border-[#E5E5E0] p-6 shadow-2xl transition-all z-10 text-[#171817]">
        {/* Header */}
        <div className="flex items-start justify-between pb-4 border-b border-[#E5E5E0]">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-[#B69A63]" />
              <h3 className="text-lg font-bold text-[#171817]">Assign Executive Task</h3>
            </div>
            <p className="text-xs text-[#626560] mt-0.5">
              Broadcast a directive to all executives or assign to a specific individual.
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-[#90928E] hover:text-[#171817] hover:bg-[#F4F4F1] transition cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Feedback Alerts */}
        {error && (
          <div className="mt-4 p-3 rounded-xl bg-[#FFF1F0] border border-[#FECDCA] text-xs font-medium text-[#B42318] flex items-center gap-2">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {successMsg && (
          <div className="mt-4 p-3 rounded-xl bg-[#EDF5F0] border border-[#D3E5D9] text-xs font-medium text-[#2D5A3C] flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 shrink-0" />
            <span>{successMsg}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="mt-5 space-y-4">
          {/* Target Selector: All vs Specific */}
          <div>
            <label className="block text-xs font-semibold text-[#171817] mb-1.5">
              Assignment Scope
            </label>
            <div className="grid grid-cols-2 gap-2 p-1 bg-[#F4F4F1] rounded-xl border border-[#E5E5E0]">
              <button
                type="button"
                onClick={() => setTarget('ALL')}
                className={`py-2 px-3 rounded-lg text-xs font-semibold flex items-center justify-center gap-2 transition cursor-pointer ${
                  target === 'ALL'
                    ? 'bg-[#111314] text-[#F4F2EC] shadow-xs'
                    : 'text-[#626560] hover:text-[#171817]'
                }`}
              >
                <Users className="w-3.5 h-3.5" />
                All Executives (Broadcast)
              </button>
              <button
                type="button"
                onClick={() => setTarget('SPECIFIC')}
                className={`py-2 px-3 rounded-lg text-xs font-semibold flex items-center justify-center gap-2 transition cursor-pointer ${
                  target === 'SPECIFIC'
                    ? 'bg-[#111314] text-[#F4F2EC] shadow-xs'
                    : 'text-[#626560] hover:text-[#171817]'
                }`}
              >
                <User className="w-3.5 h-3.5" />
                Specific Executive
              </button>
            </div>
          </div>

          {/* Specific Executive Dropdown */}
          {target === 'SPECIFIC' && (
            <div>
              <label className="block text-xs font-semibold text-[#171817] mb-1.5">
                Select Executive
              </label>
              <select
                value={selectedExecutiveId}
                onChange={(e) => setSelectedExecutiveId(e.target.value)}
                disabled={fetchingUsers}
                className="w-full text-xs font-medium px-3.5 py-2.5 rounded-xl border border-[#E5E5E0] bg-white text-[#171817] focus:outline-hidden focus:ring-1 focus:ring-[#B69A63] focus:border-[#B69A63]"
              >
                {executives.map((exec) => (
                  <option key={exec.id} value={exec.id}>
                    {exec.name} ({exec.email})
                  </option>
                ))}
              </select>
              {executives.length === 0 && !fetchingUsers && (
                <p className="text-[11px] text-[#B42318] mt-1">No active executives found in system.</p>
              )}
            </div>
          )}

          {/* Task Title */}
          <div>
            <label className="block text-xs font-semibold text-[#171817] mb-1.5">
              Task Directive / Title <span className="text-[#B42318]">*</span>
            </label>
            <input
              type="text"
              required
              placeholder="e.g. Complete 50 client outreach calls today"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full text-xs font-medium px-3.5 py-2.5 rounded-xl border border-[#E5E5E0] bg-white text-[#171817] placeholder:text-[#90928E] focus:outline-hidden focus:ring-1 focus:ring-[#B69A63] focus:border-[#B69A63]"
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-semibold text-[#171817] mb-1.5">
              Instructions / Description (Optional)
            </label>
            <textarea
              rows={2}
              placeholder="Provide context, required logs, or specific targets..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full text-xs font-medium px-3.5 py-2.5 rounded-xl border border-[#E5E5E0] bg-white text-[#171817] placeholder:text-[#90928E] focus:outline-hidden focus:ring-1 focus:ring-[#B69A63] focus:border-[#B69A63] resize-none"
            />
          </div>

          {/* Priority & Deadline Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {/* Priority */}
            <div>
              <label className="block text-xs font-semibold text-[#171817] mb-1.5">
                Priority
              </label>
              <select
                value={priority}
                onChange={(e) => setPriority(e.target.value as any)}
                className="w-full text-xs font-medium px-3 py-2 rounded-xl border border-[#E5E5E0] bg-white text-[#171817] focus:outline-hidden focus:ring-1 focus:ring-[#B69A63]"
              >
                <option value="NORMAL">Normal</option>
                <option value="HIGH">High Priority 🔥</option>
                <option value="LOW">Low</option>
              </select>
            </div>

            {/* Due Date */}
            <div>
              <label className="block text-xs font-semibold text-[#171817] mb-1.5 flex items-center gap-1">
                <Calendar className="w-3.5 h-3.5 text-[#626560]" /> Due Date
              </label>
              <input
                type="date"
                required
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
                className="w-full text-xs font-medium px-3 py-2 rounded-xl border border-[#E5E5E0] bg-white text-[#171817] focus:outline-hidden focus:ring-1 focus:ring-[#B69A63]"
              />
            </div>

